        def _ma(title, body):
            """Return HTML-safe data-modal-title / data-modal-body attr strings."""
            t = title.replace('"', '&quot;')
            b = body.replace('"', '&quot;')
            return f'data-modal-title="{t}" data-modal-body="{b}"'

