def _tab_guide() -> str:
    """Field Guide tab — explains every badge, score, and concept shown in signal cards."""

    def _section(title, color, icon, rows):
        """rows = list of (term, definition) tuples."""
        items = ""
        for term, defn in rows:
            items += (
                f'<div style="padding:10px 14px;border-bottom:1px solid var(--border)">'
                f'<div style="font-size:11px;font-weight:800;color:{color};margin-bottom:3px">{term}</div>'
                f'<div style="font-size:11.5px;color:var(--text);line-height:1.55">{defn}</div>'
                f'</div>'
            )
        return (
            f'<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;'
            f'overflow:hidden;margin-bottom:18px">'
            f'<div style="background:{color}10;padding:11px 16px;border-bottom:1px solid var(--border);'
            f'display:flex;align-items:center;gap:8px">'
            f'<span style="font-size:15px">{icon}</span>'
            f'<span style="font-size:12px;font-weight:900;color:{color};text-transform:uppercase;'
            f'letter-spacing:.8px">{title}</span>'
            f'</div>'
            f'{items}'
            f'</div>'
        )

    def _badge(label, bg, color, tip=""):
        return (f'<span style="background:{bg};color:{color};font-size:10px;font-weight:700;'
                f'padding:2px 8px;border-radius:4px;margin-right:4px">{label}</span>')

    # ── Section content ────────────────────────────────────────────────────────

    verdict_rows = [
        ("BUY " + _badge("BUY","#dcfce7","#166534"),
         "All thresholds met for the current regime: score ≥ regime min, R:R ≥ 3:1 (4:1 in Risk-Off), "
         "RS ≥ regime min, entry quality not MISSED, no gate failures. Act within the entry zone."),
        ("WATCH " + _badge("WATCH","#fef3c7","#92400e"),
         "Below one or more BUY thresholds — usually score, RS rank, or entry quality. "
         "Set a price alert at the entry zone and revisit when conditions improve. Not tradeable yet."),
        ("AVOID / SHORT " + _badge("SHORT","#fee2e2","#991b1b"),
         "For longs: failed a hard gate (earnings blackout, liquidity, panic regime, MISSED entry). "
         "For shorts: bear score threshold met in a bearish regime."),
    ]

    score_rows = [
        ("Score /100 — 5-Pillar System",
         "The composite score is built from five weighted pillars. Each pillar is scored independently "
         "and normalized to its weight. A score of 80+ is strong; 70–79 is solid; below 65 is marginal."),
        ("⚙️ Tech Structure (35 pts)",
         "EMA stack (8/21/50/200), ADX trend strength, RSI/MACD momentum, RVOL, OBV, "
         "S/R structure, RS rank vs SPY, weekly EMA alignment, ADX+DI cross, VWAP, candle patterns."),
        ("⚡ Catalyst Quality (20 pts)",
         "What is actually driving the move. Scores the type and strength of the catalyst "
         "— earnings surprise, options flow, breakout, squeeze, or pure momentum. "
         "Catalyst T1 contributes more than T3."),
        ("📊 RS + Sector (20 pts)",
         "Relative strength of the stock vs SPY (RS Rank 0–100), plus whether the stock's sector "
         "is rotating into favour vs SPY over 63 days. Sector outperformance adds a 10% bonus."),
        ("🏦 Smart Money (15 pts)",
         "Unusual options activity (UOA), institutional holding trends, insider buy/sell activity, "
         "short interest, and days-to-cover (squeeze risk)."),
        ("🛡️ Quality Gate (10 pts)",
         "Fundamental health: revenue growth, margin quality, EPS growth trend, balance sheet, "
         "PEG ratio, analyst consensus. Acts as a tiebreaker for otherwise equal setups."),
    ]

    regime_rows = [
        (_badge("Risk-On Trending","#dcfce7","#166534") + " — BUY ≥ 65, R:R ≥ 3.0, RS ≥ 80",
         "VIX &lt; 18, breadth &gt; 65% of stocks above 50d EMA, SPY above both EMAs. "
         "Full aggression. All setup families valid. Full position sizing (100%)."),
        (_badge("Risk-On Choppy","#fef3c7","#92400e") + " — BUY ≥ 72, R:R ≥ 3.0, RS ≥ 75",
         "Market is up but choppy — uncertain breadth or elevated VIX (18–25). "
         "Prefer pullbacks, PEAD, UOA, high-quality continuations. Size 70% of normal."),
        (_badge("Risk-Off Trending","#fee2e2","#991b1b") + " — BUY ≥ 78, R:R ≥ 4.0, RS ≥ 80",
         "SPY below 50d EMA or downtrending. Only elite leaders with exceptional catalysts. "
         "Max 35% of normal position size. Defensive sectors preferred."),
        (_badge("PANIC","#1e293b","#f87171") + " — No new longs",
         "VIX &gt; 35 or fewer than 20% of stocks above their 50d EMA. "
         "Capital preservation mode. Existing positions managed to exits only."),
    ]

    tier_rows = [
        (_badge("T1","#dbeafe","#1d4ed8"),
         "Highest conviction. ALL of: score ≥ 88, RS ≥ 85, R:R ≥ 3.5, regime = Risk-On Trending, "
         "catalyst tier = T1, entry quality = FRESH or PULLBACK. "
         "Use 8–10% allocation. Rare — expect 1–3 per month in a good regime."),
        (_badge("T2","#e0f2fe","#0891b2"),
         "Standard quality trade. Score ≥ 78, RS ≥ 75, R:R ≥ 3.0, regime ≠ Panic, "
         "catalyst tier ≤ T2, quality entry. Use 5–7.5% allocation. "
         "Core of the trading book — target 2–4 concurrent T2 positions."),
        (_badge("T3","#ede9fe","#6d28d9"),
         "Lower conviction. Score ≥ 70, R:R ≥ 3.0. One or more quality criteria missed "
         "(RS, regime, catalyst). Use 3–5% allocation. "
         "Treat as a speculative small position, not a core trade."),
    ]

    catalyst_rows = [
        (_badge("Cat T1","#ede9fe","#7c3aed"),
         "<b>Highest urgency.</b> PEAD (Post-Earnings Announcement Drift — stock gapping up on earnings surprise), "
         "UOA (Unusual Options Activity — smart money positioning before a move), "
         "VCP breakout (Volatility Contraction Pattern), 52-week high breakout. "
         "These are time-sensitive: the window closes in days."),
        (_badge("Cat T2","#e0f2fe","#0891b2"),
         "<b>Mid-strength.</b> Squeeze expansion, EMA21/50 pullback, institutional flow "
         "(increasing holdings), insider cluster (multiple buys in 30 days). "
         "Good setups but require technical confirmation before entry."),
        (_badge("Cat T3","#f8fafc","#64748b"),
         "<b>Weakest.</b> Analyst price target upgrade, general momentum continuation, "
         "social sentiment spike. The thesis rests mainly on technicals, not a specific event. "
         "Still tradeable but use tighter size and expect slower moves."),
    ]

    entry_q_rows = [
        (_badge("FRESH","#dcfce7","#059669"),
         "Optimal. Price is within 0.75 ATR of the support level or EMA21. "
         "You are entering right at the logical support — stop is tight, R:R is maximised. Enter now."),
        (_badge("PULLBACK","#e0f2fe","#0891b2"),
         "Good. Price has pulled back within 1.25 ATR of EMA8, EMA21, EMA50, or a key support level. "
         "Slightly less optimal than FRESH but still a quality entry. Risk is well-defined."),
        (_badge("VALID","#f1f5f9","#475569"),
         "Acceptable. Within 1.25 ATR of a pivot. Not ideal but within risk tolerances. "
         "Consider waiting for a shallower pullback if you have time."),
        (_badge("EXTENDED","#fef3c7","#d97706"),
         "Caution. Price is 1.25–2.0 ATR above the pivot or EMA21. "
         "You are chasing a move. The system requires an extra 10 score points to approve a BUY here. "
         "Waiting for a pullback will nearly always produce a better trade."),
        (_badge("MISSED","#fee2e2","#dc2626"),
         "Do not enter. Price is more than 2.0 ATR above the pivot. "
         "Entering here destroys the R:R ratio. Wait for a pullback to the next support or EMA, "
         "then re-evaluate as a FRESH or PULLBACK entry."),
    ]

    subtype_rows = [
        ("Pivot Entry",
         "First entry right at the breakout pivot or support level. Lowest risk. Best R:R. "
         "This is the ideal entry for any setup."),
        ("First Pullback",
         "First pullback after the initial breakout. Classic stage-2 add point. "
         "Slightly higher entry than Pivot but confirmed breakout reduces false-break risk."),
        ("EMA21 Continuation",
         "Price pulled back to the rising 21-day EMA during an uptrend. "
         "One of the most reliable trend-following entries. Stop goes just below EMA21."),
        ("EMA50 Continuation",
         "Deeper pullback to the 50-day EMA. Requires strong underlying trend conviction. "
         "Better R:R than EMA21 entry but needs volume and sector confirmation."),
        ("Tight Range Rebreak",
         "Stock compressed into a tight range (low ATR) and is breaking out again. "
         "Volatility contraction followed by expansion. Clean stop just below the range."),
        ("Breakout Add",
         "Adding to an existing position after the initial breakout has already occurred and confirmed. "
         "Higher risk than a Pivot Entry. Only valid with positive open profit on the base position."),
    ]

    family_rows = [
        (_badge("Impulse Catalyst","#ede9fe","#7c3aed") + " · Hold 5–8 days",
         "Fast-moving, event-driven. Triggered by PEAD, unusual options, or gap-and-go on news. "
         "Trade the momentum window aggressively — take 50% profit at T1, trail the rest. "
         "Exit before day 8 regardless; impulse windows close fast."),
        (_badge("Breakout Expansion","#dbeafe","#1d4ed8") + " · Hold 7–21 days",
         "Classic stage-2 breakout from a VCP, squeeze, or 52-week high. "
         "Needs above-average volume on the breakout day. Ride the expansion phase; "
         "re-evaluate at 14 days if still open."),
        (_badge("Trend Continuation","#dcfce7","#059669") + " · Hold 7–21 days",
         "Stock in a confirmed uptrend pulling back to EMA21 or EMA50. "
         "The trend is your edge — enter on the bounce, hold as long as the EMA stack holds. "
         "Exit on a close below EMA21 after T1 is hit."),
        (_badge("Special Situation","#fef3c7","#d97706") + " · Hold 5–15 days",
         "Non-standard catalyst: insider cluster, float rotation, short squeeze. "
         "Higher volatility and binary outcomes. Use tighter stops (1.0× ATR vs 1.5× for trend setups). "
         "Catalysts are often time-limited — have a defined exit plan before entering."),
    ]

    sizing_rows = [
        ("Base Allocation",
         "The Kelly formula calculates the theoretically optimal fraction of capital per trade "
         "based on your historical win rate and average profit/loss. "
         "Raw Kelly is scaled down to 25% for safety (fractional Kelly)."),
        ("Regime Multiplier",
         "Risk-On Trending = 1.0 (full size) · Risk-On Choppy = 0.70 · "
         "Risk-Off Trending = 0.35 · Panic = 0.0. "
         "If VIX is 22–25, an additional 0.75× VIX multiplier is applied on top."),
        ("Conviction Tier Multiplier",
         "T1 = 0.85–1.0 (full size) · T2 = 0.30–0.60 · T3 = 0.15–0.30. "
         "Final position = base × regime_mult × vix_mult × tier_mult. "
         "Hard caps: max 10% per position, max 80% gross exposure."),
        ("Beta Adjustment (β shown on card)",
         "Beta measures how much the stock moves vs the S&P 500. "
         "A stock with β 0.5 moves half as much — so you need 2× shares to match the dollar risk of a β 1.0 stock. "
         "β &gt; 1.5 triggers a downward size adjustment (already volatile enough). "
         "The '→ X% size adj' label shows the final % adjustment applied."),
        ("R:R (Reward-to-Risk Ratio)",
         "R:R = (T1 Price − Entry) ÷ (Entry − Stop). "
         "Minimum 3:1 required in Risk-On regimes. 4:1 required in Risk-Off. "
         "A 3:1 means you risk $1 to make $3. Even at a 40% win rate, 3:1 R:R is profitable."),
    ]

    trade_plan_rows = [
        ("Entry Zone (entry_lo – entry_hi)",
         "The acceptable price range for entry. Calculated as a ±1% band around the current price "
         "adjusted for ATR. If the price gaps above entry_hi on open, downgrade to WATCH and wait."),
        ("Stop",
         "The hard exit level. Calculated as 1.5× ATR below the nearest support. "
         "Close the position if price closes a full session below this level. "
         "Never widen the stop after entry — that is how small losses become large ones."),
        ("T1 — First Target",
         "Take 50% of the position off at T1. Move the stop to breakeven. "
         "T1 is typically the next resistance level or 2× risk above entry."),
        ("T2 — Second Target",
         "Hold the remaining 50% with a trailing stop at 1.5× ATR. "
         "T2 is a stretch target at the next major resistance or 3–4× risk above entry. "
         "Let this run — this is where the outsized returns come from."),
        ("Hold Period Guide",
         "The expected duration from entry to T2, by setup family. "
         "Impulse Catalyst: 5–8d. Breakout Expansion: 7–21d. "
         "Trend Continuation: 7–21d. Special Situation: 5–15d. "
         "Exit at day-max regardless of profit/loss if T1 has not been hit."),
    ]

    # ── Assemble ───────────────────────────────────────────────────────────────
    col1 = (
        _section("Verdict — BUY / WATCH / SHORT", "#059669", "🎯", verdict_rows) +
        _section("Score /100 — 5 Pillars", "#0891b2", "📊", score_rows) +
        _section("Market Regime", "#7c3aed", "🌐", regime_rows) +
        _section("Entry Quality (ATR-relative)", "#d97706", "📍", entry_q_rows)
    )
    col2 = (
        _section("Conviction Tiers — T1 / T2 / T3", "#1d4ed8", "🏆", tier_rows) +
        _section("Catalyst Tiers — Cat T1 / T2 / T3", "#7c3aed", "⚡", catalyst_rows) +
        _section("Entry Subtypes", "#0891b2", "🔍", subtype_rows) +
        _section("Setup Families & Hold Periods", "#059669", "📅", family_rows) +
        _section("Position Sizing", "#475569", "💰", sizing_rows) +
        _section("Trade Plan Fields", "#0891b2", "📋", trade_plan_rows)
    )

    tip_note = (
        '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;'
        'padding:12px 16px;margin-bottom:20px;display:flex;align-items:center;gap:10px">'
        '<span style="font-size:18px">💡</span>'
        '<span style="font-size:11.5px;color:var(--text-muted);line-height:1.5">'
        '<b style="color:var(--text)">Quick tip:</b> Hover over any badge on a signal card '
        '(BUY, T2, Cat T1, EXTENDED, Trend Continuation…) to see a one-line tooltip explaining that field. '
        'This guide has the full detail behind each concept.'
        '</span></div>'
    )

    return (
        f'<div style="padding:20px 24px;max-width:1400px">'
        f'<div style="margin-bottom:20px">'
        f'<div style="font-size:18px;font-weight:900;color:var(--text);margin-bottom:4px">📖 Field Guide</div>'
        f'<div style="font-size:12px;color:var(--text-muted)">Every badge, score, and label explained — hover badges on signal cards for quick tooltips.</div>'
        f'</div>'
        f'{tip_note}'
        f'<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start">'
        f'<div>{col1}</div>'
        f'<div>{col2}</div>'
        f'</div>'
        f'</div>'
    )


def _tab_leveraged_etfs(all_scored: list[dict], killed: list[dict]) -> str:
    """
    Leveraged ETFs tab — organized by category.
    Shows BUY/WATCH/AVOID verdicts for all tracked leveraged instruments.
    """
    leveraged_watchlist = {
        "Index Leveraged (3x)": ["TQQQ", "SOXL", "UPRO", "SPXL", "TNA", "TECL", "FAS", "FNGU", "BULZ", "WANT"],
        "Single-Stock Leveraged": ["NVDL", "TSLL", "AAPB", "MSFU", "AMZU", "GGLL", "CONL", "MSTU"],
        "Miners & Metals": ["NUGT", "JNUG", "BOIL", "UCO", "AGQ", "UGL"],
        "Sector Leveraged": ["CURE", "DRN", "DPST", "TPOR", "NAIL", "RETL", "WEBL", "LABU"],
        "International": ["YINN", "INDL"],
    }

    # Build lookup
    scored_map = {r.get("ticker", ""): r for r in all_scored + killed}

    def verdict_badge(ticker: str) -> tuple:
        """Return (verdict, color, emoji) for a ticker."""
        r = scored_map.get(ticker, {})
        verdict = r.get("decision", {}).get("verdict", "—")
        if verdict == "BUY":
            return "BUY", "#059669", "✓"
        elif verdict == "WATCH":
            return "WATCH", "#f59e0b", "◆"
        elif verdict == "AVOID":
            return "AVOID", "#dc2626", "✕"
        else:
            return "—", "#9ca3af", "—"

    html = '<div style="padding:20px">'
    html += '<div style="font-size:20px;font-weight:800;margin-bottom:20px">⚡ Leveraged ETF Dashboard</div>'

    for category, tickers in leveraged_watchlist.items():
        cat_results = [scored_map.get(t, {}) for t in tickers if t in scored_map]
        cat_count = len(cat_results)
        buy_count = sum(1 for r in cat_results if r.get("decision", {}).get("verdict") == "BUY")
        watch_count = sum(1 for r in cat_results if r.get("decision", {}).get("verdict") == "WATCH")

        html += f'<div style="background:var(--surface-alt);border-radius:12px;padding:16px;margin-bottom:16px">'
        html += f'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">'
        html += f'<div style="font-weight:700;font-size:14px;color:var(--text)">{category}</div>'
        html += f'<div style="font-size:11px;color:var(--text-muted)">{cat_count} tracked</div>'
        html += f'</div>'

        html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px">'
        for ticker in tickers:
            r = scored_map.get(ticker)
            if not r:
                # Show unanalyzed tickers too
                html += f'<div onclick="fsOpen(\'{ticker}\')" style="cursor:pointer;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px;text-align:center">'
                html += f'<div style="font-weight:800;font-size:15px;color:var(--text)">{ticker}</div>'
                html += f'<div style="font-size:11px;color:var(--text-muted);margin:4px 0">Not Analyzed</div>'
                html += f'<div style="background:#1e293b;color:#64748b;padding:4px 8px;border-radius:4px;font-size:10px;font-weight:700">— N/A</div>'
                html += f'</div>'
                continue
            verdict, color, emoji = verdict_badge(ticker)
            price = r.get("price", 0)
            score = r.get("score", 0)
            # EMA distances & performance
            ind = r.get("technicals", {}).get("indicators", {})
            _p = price or 1
            ema20 = ind.get("ema20") or ind.get("ema21")
            ema50 = ind.get("ema50")
            ema200 = ind.get("ema200")
            d20 = round((_p - ema20) / ema20 * 100, 1) if ema20 else None
            d50 = round((_p - ema50) / ema50 * 100, 1) if ema50 else None
            d200 = round((_p - ema200) / ema200 * 100, 1) if ema200 else None
            rsi = ind.get("rsi")
            perf_1w = round(ind.get("perf_1w", 0) or 0, 1) if ind.get("perf_1w") else None
            perf_1m = round(ind.get("perf_1m", 0) or 0, 1) if ind.get("perf_1m") else None

            def _dc(v):
                if v is None: return "#64748b"
                return "#4ade80" if v > 0 else "#ef4444"

            html += f'<div onclick="fsOpen(\'{ticker}\')" style="cursor:pointer;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px;text-align:center">'
            html += f'<div style="font-weight:800;font-size:15px;color:var(--text)">{ticker}</div>'
            html += f'<div style="font-size:14px;font-weight:700;color:var(--text);margin:4px 0">${price:.2f}</div>'
            html += f'<div style="display:flex;justify-content:center;gap:6px;margin:6px 0;flex-wrap:wrap">'
            if d20 is not None:
                html += f'<span style="font-size:9px;padding:2px 6px;border-radius:4px;background:rgba(255,255,255,.05);color:{_dc(d20)}">E20 {d20:+.1f}%</span>'
            if d50 is not None:
                html += f'<span style="font-size:9px;padding:2px 6px;border-radius:4px;background:rgba(255,255,255,.05);color:{_dc(d50)}">E50 {d50:+.1f}%</span>'
            if d200 is not None:
                html += f'<span style="font-size:9px;padding:2px 6px;border-radius:4px;background:rgba(255,255,255,.05);color:{_dc(d200)}">E200 {d200:+.1f}%</span>'
            html += f'</div>'
            if rsi is not None:
                rsi_c = "#4ade80" if 50 <= rsi <= 70 else "#ef4444" if rsi > 70 or rsi < 30 else "#f59e0b"
                html += f'<div style="font-size:10px;color:{rsi_c};margin-bottom:4px">RSI {rsi:.0f}</div>'
            html += f'<div style="font-size:10px;color:var(--text-muted);margin-bottom:6px">Score: {score:.0f}</div>'
            html += f'<div style="background:{color};color:white;padding:4px 8px;border-radius:4px;font-size:10px;font-weight:700">{emoji} {verdict}</div>'
            html += f'</div>'  # close ticker card (opened line 17705)

        html += '</div>'  # close grid (opened line 17674)
        html += '</div>'  # close category card (opened line 17668)

    html += '</div>'  # close outer padding wrapper (opened line 17659)
    return html


def _tab_themes(all_scored: list[dict], buy_candidates: list[dict], watch_list: list[dict]) -> str:
    """
    Thematic sector map — visually rich 2-column tile grid.
    Each tile has a colored gradient header, grouped ticker pills pre-colored from
    today's scan, a Scan Sector button that runs live /api/analyze/ per ticker and
    updates pills inline with verdict + score, and a progress bar + summary badge.
    """
    import re as _re

    # ── Verdict map from today's scan ─────────────────────────────────────────
    verdict: dict[str, str] = {}
    score_map: dict[str, int] = {}
    for r in all_scored:
        t = r.get("ticker", "")
        verdict[t]   = r.get("decision", {}).get("verdict", "")
        score_map[t] = int(r.get("score", 0))
    for r in buy_candidates:
        t = r.get("ticker", "")
        if t and t not in verdict:
            verdict[t] = "BUY"
    for r in watch_list:
        t = r.get("ticker", "")
        if t and t not in verdict:
            verdict[t] = "WATCH"

    # ── Helpers ───────────────────────────────────────────────────────────────
    def _slug(name: str) -> str:
        return _re.sub(r"[^a-z0-9]", "", name.lower())[:16]

    def _pill(ticker: str, card_id: str) -> str:
        v  = verdict.get(ticker, "")
        sc = score_map.get(ticker)
        pid = f"thp-{card_id}-{ticker}"

        if v == "BUY":
            bg, fg, bdr = "#dcfce7", "#15803d", "#86efac"
            glow = "box-shadow:0 0 0 2px #86efac;"
            sc_html = f' <span style="font-size:10px;font-weight:900">{sc}</span>' if sc else ""
            oc = f"spOpen('{ticker}')"
        elif v == "WATCH":
            bg, fg, bdr = "#fef9c3", "#854d0e", "#fde047"
            glow = "box-shadow:0 0 0 2px #fde047;"
            sc_html = f' <span style="font-size:10px;font-weight:900">{sc}</span>' if sc else ""
            oc = f"spOpen('{ticker}')"
        elif v:  # AVOID — in scan but no signal
            bg, fg, bdr = "#f1f5f9", "#64748b", "#e2e8f0"
            glow = ""
            sc_html = f' <span style="font-size:10px">{sc}</span>' if sc else ""
            oc = f"spOpen('{ticker}')"
        else:   # unscanned
            bg, fg, bdr = "#f8fafc", "#94a3b8", "#e2e8f0"
            glow = ""
            sc_html = ""
            oc = f"stLiveAnalyze('{ticker}')"

        return (
            f'<span id="{pid}" data-ticker="{ticker}" onclick="{oc}" '
            f'style="display:inline-flex;align-items:center;gap:2px;background:{bg};color:{fg};'
            f'border:1px solid {bdr};padding:4px 10px;border-radius:20px;font-size:12px;'
            f'font-weight:700;cursor:pointer;transition:all .2s;{glow}margin:3px;white-space:nowrap">'
            f'{ticker}{sc_html}</span>'
        )

    def _sector_tile(name: str, icon: str, color: str, groups: list) -> str:
        cid = _slug(name)

        # Collect all unique tickers for this sector (for JS scan list)
        all_tickers: list[str] = []
        seen: set[str] = set()
        for _, tickers in groups:
            for t in tickers:
                if t not in seen:
                    all_tickers.append(t)
                    seen.add(t)

        tickers_js = "[" + ",".join(f"'{t}'" for t in all_tickers) + "]"

        # Pre-compute initial BUY/WATCH/AVOID counts from today's scan
        buy_n   = sum(1 for t in all_tickers if verdict.get(t) == "BUY")
        watch_n = sum(1 for t in all_tickers if verdict.get(t) == "WATCH")
        avoid_n = sum(1 for t in all_tickers if verdict.get(t) == "AVOID")
        total_n = len(all_tickers)

        # Show pre-scan summary only if we have any scanned tickers
        scanned_n = buy_n + watch_n + avoid_n
        if scanned_n:
            summary_init = (
                f'<span style="color:#15803d;font-weight:700">{buy_n} BUY</span> &nbsp;'
                f'<span style="color:#854d0e;font-weight:700">{watch_n} WATCH</span> &nbsp;'
                f'<span style="color:#64748b">{avoid_n} AVOID</span>'
                f'<span style="color:var(--text-muted)"> &nbsp;·&nbsp; {total_n - scanned_n} unscanned</span>'
            )
        else:
            summary_init = f'<span style="color:var(--text-muted)">{total_n} tickers — click Scan to analyze</span>'

        # Group rows
        rows = ""
        for group_name, tickers in groups:
            pills = "".join(_pill(t, cid) for t in tickers)
            rows += (
                f'<div data-group="{group_name}" style="display:flex;align-items:flex-start;'
                f'gap:10px;padding:7px 0;border-bottom:1px solid {color}18">'
                f'<div style="min-width:160px;font-size:11px;font-weight:600;color:{color}cc;'
                f'padding-top:6px;flex-shrink:0;letter-spacing:.2px">{group_name}</div>'
                f'<div style="flex:1;display:flex;flex-wrap:wrap">{pills}</div>'
                f'</div>'
            )

        return (
            # Tile wrapper
            f'<div data-card="{name}" style="background:var(--surface);border:1px solid {color}33;'
            f'border-radius:16px;overflow:hidden;display:flex;flex-direction:column;'
            f'box-shadow:0 2px 12px {color}12">'

            # Header — gradient + icon + name + scan button
            f'<div style="background:linear-gradient(135deg,{color}22 0%,{color}08 100%);'
            f'border-bottom:2px solid {color};padding:14px 16px;'
            f'display:flex;align-items:center;gap:12px">'
            f'<div style="width:42px;height:42px;background:{color}20;border-radius:10px;'
            f'display:flex;align-items:center;justify-content:center;font-size:22px;flex-shrink:0">'
            f'{icon}</div>'
            f'<div style="flex:1;min-width:0">'
            f'<div style="font-weight:800;font-size:13px;color:{color};line-height:1.2">{name}</div>'
            f'<div id="thsum-{cid}" style="font-size:11px;margin-top:3px;line-height:1.4">{summary_init}</div>'
            f'</div>'
            f'<button id="thbtn-{cid}" onclick="thScanSector(\'{cid}\',{tickers_js})" '
            f'style="background:{color};color:#fff;border:none;border-radius:8px;'
            f'padding:7px 14px;font-weight:700;font-size:12px;cursor:pointer;'
            f'white-space:nowrap;letter-spacing:.3px;flex-shrink:0">'
            f'&#128270; Scan</button>'
            f'</div>'

            # Progress bar (hidden until scan starts)
            f'<div id="thprog-{cid}" style="height:3px;background:{color}20;display:none">'
            f'<div id="thprogbar-{cid}" style="height:3px;background:{color};width:0%;'
            f'transition:width .3s"></div>'
            f'</div>'

            # Groups
            f'<div style="padding:4px 16px 12px">{rows}</div>'
            f'</div>'
        )

    # ── Build 2-column grid ───────────────────────────────────────────────────
    tiles = "".join(_sector_tile(n, ic, c, g) for n, ic, c, g in THEMES)

    # ── Toolbar: search + legend ──────────────────────────────────────────────
    toolbar = (
        '<div style="display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:18px">'

        # Search
        '<input id="theme-search" type="text" placeholder="&#128269; Filter by ticker or group…" '
        'oninput="themeFilter(this.value)" '
        'style="padding:8px 14px;border:1px solid var(--border);border-radius:20px;'
        'font-size:13px;font-family:inherit;background:var(--surface);color:var(--text);min-width:240px;outline:none">'

        # Scan All button
        '<button onclick="thScanAll()" '
        'style="background:var(--primary);color:#fff;border:none;border-radius:20px;'
        'padding:8px 18px;font-weight:700;font-size:12px;cursor:pointer;letter-spacing:.3px">'
        '&#9889; Scan All Sectors</button>'

        # Legend pills
        '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-left:auto">'
        '<span style="background:rgba(34,197,94,0.15);color:#4ade80;border:1px solid rgba(34,197,94,0.30);padding:3px 10px;'
        'border-radius:20px;font-size:11px;font-weight:700">TICK 88 &nbsp;BUY</span>'
        '<span style="background:rgba(245,158,11,0.15);color:#fbbf24;border:1px solid rgba(245,158,11,0.30);padding:3px 10px;'
        'border-radius:20px;font-size:11px;font-weight:700">TICK 65 &nbsp;WATCH</span>'
        '<span style="background:rgba(239,68,68,0.12);color:#f87171;border:1px solid rgba(239,68,68,0.25);padding:3px 10px;'
        'border-radius:20px;font-size:11px;font-weight:700">TICK &nbsp;AVOID</span>'
        '<span style="background:rgba(100,116,139,0.12);color:#94a3b8;border:1px solid var(--border);padding:3px 10px;'
        'border-radius:20px;font-size:11px;font-weight:700">TICK &nbsp;unscanned</span>'
        '</div>'
        '</div>'
    )

    # ── JS: scan logic + filter ───────────────────────────────────────────────
    js = '''<script>
/* ── Theme scan engine ── */
async function thScanSector(cid, tickers) {
  var btn    = document.getElementById('thbtn-' + cid);
  var prog   = document.getElementById('thprog-' + cid);
  var bar    = document.getElementById('thprogbar-' + cid);
  var sumEl  = document.getElementById('thsum-' + cid);

  btn.disabled = true;
  btn.textContent = 'Scanning…';
  prog.style.display = 'block';

  var total = tickers.length, done = 0;
  var counts = {BUY: 0, WATCH: 0, AVOID: 0, err: 0};

  for (var i = 0; i < tickers.length; i++) {
    var t = tickers[i];
    try {
      var d;
      if (typeof ST_DATA !== 'undefined' && ST_DATA[t]) {
        d = ST_DATA[t];
      } else {
        var resp = await fetch('/api/analyze/' + t);
        var raw  = await resp.json();
        if (raw.error) throw new Error(raw.error);
        d = _apiToStData(raw);
        if (typeof ST_DATA !== 'undefined') ST_DATA[t] = d;
      }
      var v = (d.verdict || 'AVOID').toUpperCase();
      counts[v] = (counts[v] || 0) + 1;
      thUpdatePill(cid, t, d);
    } catch(e) { counts.err++; }
    done++;
    bar.style.width = Math.round(done / total * 100) + '%';
  }

  // Summary
  var s = '<span style="color:#15803d;font-weight:700">' + (counts.BUY||0) + ' BUY</span> &nbsp;'
        + '<span style="color:#854d0e;font-weight:700">' + (counts.WATCH||0) + ' WATCH</span> &nbsp;'
        + '<span style="color:#64748b">' + (counts.AVOID||0) + ' AVOID</span>';
  if (counts.err) s += ' <span style="color:#b91c1c">&nbsp;·&nbsp; ' + counts.err + ' failed</span>';
  sumEl.innerHTML = s;

  prog.style.display = 'none';
  bar.style.width = '0%';
  btn.disabled = false;
  btn.textContent = '↺ Rescan';
}

function thUpdatePill(cid, ticker, d) {
  var el = document.getElementById('thp-' + cid + '-' + ticker);
  if (!el) return;
  var v  = (d.verdict || 'AVOID').toUpperCase();
  var sc = Math.round(d.score || 0);
  var bg = v === 'BUY' ? '#dcfce7' : v === 'WATCH' ? '#fef9c3' : '#f1f5f9';
  var fg = v === 'BUY' ? '#15803d' : v === 'WATCH' ? '#854d0e' : '#64748b';
  var br = v === 'BUY' ? '#86efac' : v === 'WATCH' ? '#fde047' : '#e2e8f0';
  var gw = v === 'BUY' ? 'box-shadow:0 0 0 2px #86efac;' : v === 'WATCH' ? 'box-shadow:0 0 0 2px #fde047;' : '';
  el.style.cssText = el.style.cssText
    .replace(/background:[^;]+;/, 'background:' + bg + ';')
    .replace(/color:[^;]+;/, 'color:' + fg + ';')
    .replace(/border:[^;]+;/, 'border:1px solid ' + br + ';');
  el.style.boxShadow = v === 'BUY' ? '0 0 0 2px #86efac' : v === 'WATCH' ? '0 0 0 2px #fde047' : 'none';
  el.innerHTML = ticker + ' <span style="font-size:10px;font-weight:900">' + sc + '</span>';
  el.onclick = function() { spOpen(ticker); };
  // Brief flash animation
  el.style.transform = 'scale(1.12)';
  setTimeout(function() { el.style.transform = 'scale(1)'; }, 200);
}

async function thScanAll() {
  var btns = document.querySelectorAll('[id^="thbtn-"]');
  for (var i = 0; i < btns.length; i++) {
    if (!btns[i].disabled) btns[i].click();
    await new Promise(function(r){setTimeout(r, 200);});
  }
}

/* ── Theme filter ── */
function themeFilter(q) {
  q = q.trim().toUpperCase();
  document.querySelectorAll('#theme-grid [data-ticker]').forEach(function(el) {
    el.style.display = (!q || el.dataset.ticker.includes(q)) ? '' : 'none';
  });
  document.querySelectorAll('#theme-grid [data-group]').forEach(function(row) {
    var vis = Array.from(row.querySelectorAll('[data-ticker]')).some(function(e){return e.style.display !== 'none';});
    row.style.display = vis ? '' : 'none';
  });
  document.querySelectorAll('#theme-grid [data-card]').forEach(function(card) {
    var vis = Array.from(card.querySelectorAll('[data-group]')).some(function(r){return r.style.display !== 'none';});
    card.style.display = vis ? '' : 'none';
  });
}
</script>'''

    return (
        '<div style="padding:16px 20px">'
        + toolbar
        + '<div id="theme-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(560px,1fr));gap:16px">'
        + tiles
        + '</div>'
        + js
        + '</div>'
    )


#  STRATEGIES TAB
# ─────────────────────────────────────────────────────────────────────────────


_CORE_VERDICTS: dict = {}

def _strategy_tile(ticker, strategy, price, stop, target, rr, rs, score, wr, detail="", hold="5-10d", profit_est=0, earnings_warning=None):
    """Reusable tile card for strategy candidates."""
    rr_col = "#4ade80" if rr >= 2.5 else "#fbbf24" if rr >= 1.5 else "#94a3b8"
    score_col = "#4ade80" if score >= 80 else "#fbbf24" if score >= 60 else "#94a3b8"

    # Core-engine verdict pill (Vinod review — strategy screeners must show verdict too)
    _v = (_CORE_VERDICTS.get(ticker) or "—").upper()
    _v_colors = {
        "BUY":   ("#4ade80", "rgba(74,222,128,.15)", "rgba(74,222,128,.35)"),
        "SHORT": ("#c4b5fd", "rgba(124,58,237,.18)", "rgba(124,58,237,.40)"),
        "WATCH": ("#fbbf24", "rgba(251,191,36,.12)", "rgba(251,191,36,.30)"),
        "SELL":  ("#f87171", "rgba(248,113,113,.12)", "rgba(248,113,113,.30)"),
        "AVOID": ("#94a3b8", "rgba(148,163,184,.12)", "rgba(148,163,184,.28)"),
    }
    _vcol, _vbg, _vbd = _v_colors.get(_v, ("#64748b", "rgba(100,116,139,.10)", "rgba(100,116,139,.25)"))
    _verdict_pill = (
        f'<span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:800;'
        f'background:{_vbg};color:{_vcol};border:1px solid {_vbd};letter-spacing:.3px">{_v}</span>'
    )
    strat_colors = {"10-Week Pullback":"#a78bfa", "Mean Reversion":"#22d3ee", "VCP Breakout":"#4ade80",
                    "Pocket Pivot":"#fb923c", "RS New High":"#f472b6", "Insider Cluster":"#60a5fa",
                    "Gap Hold":"#34d399", "Short Squeeze":"#ef4444", "Earnings Run-Up":"#fbbf24",
                    "Sector Rotation":"#818cf8"}
    sc = strat_colors.get(strategy, "#94a3b8")
    risk = abs(price - stop) if stop else price * 0.03
    shares = int(1000 / price) if price > 0 else 0
    risk_d = round(risk * shares, 0)
    prof_d = round((target - price) * shares, 0) if target > price else 0
    pct = round((target - price) / price * 100, 1) if target > price and price > 0 else 0

    # Inline star rating for strategy tiles
    _sr = 0.0
    if rr >= 3.0: _sr += 1.5
    elif rr >= 2.0: _sr += 1.0
    elif rr >= 1.5: _sr += 0.5
    if rs >= 90: _sr += 1.0
    elif rs >= 80: _sr += 0.75
    elif rs >= 70: _sr += 0.5
    if "VCP" in strategy: _sr += 1.0
    elif "Pullback" in strategy or "Continuation" in strategy: _sr += 0.75
    elif "Mean Reversion" in strategy or "Pocket Pivot" in strategy: _sr += 0.5
    if score >= 85: _sr += 0.5
    elif score >= 70: _sr += 0.25
    if wr >= 65: _sr += 0.5
    elif wr >= 60: _sr += 0.25
    _st_star = min(5, max(1, round(_sr)))
    _st_star_html = _star_html(_st_star)

    # Earnings warning for strategy tile (Task 20)
    _st_earn_html = ""
    if earnings_warning:
        _st_ew_days = earnings_warning.get("days", 99)
        _st_ew_color = "#ef4444" if _st_ew_days <= 3 else "#f59e0b"
        _st_ew_bg = "rgba(239,68,68,.08)" if _st_ew_days <= 3 else "rgba(245,158,11,.08)"
        _st_ew_border = "rgba(239,68,68,.2)" if _st_ew_days <= 3 else "rgba(245,158,11,.2)"
        _st_earn_html = (
            f'<div style="display:flex;align-items:center;gap:6px;padding:6px 10px;border-radius:6px;'
            f'background:{_st_ew_bg};border:1px solid {_st_ew_border};margin-bottom:8px">'
            f'<span style="font-size:12px">&#9888;&#65039;</span>'
            f'<span style="font-size:10px;font-weight:700;color:{_st_ew_color}">{earnings_warning["message"]}</span>'
            f'<span style="font-size:9px;color:#94a3b8;margin-left:auto">Size down</span>'
            f'</div>'
        )

    return f'''<div class="rth-tile" style="min-height:auto" onclick="fsOpen('{ticker}')">
      <div class="rth-full" style="padding:14px">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
          <div style="font-size:18px;font-weight:900;color:#e2e8f0">{ticker}</div>
          {_st_star_html}
          <span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:{sc}18;color:{sc};border:1px solid {sc}33">{strategy}</span>
          {_verdict_pill}
          <span style="margin-left:auto;font-size:18px;font-weight:900;color:#e2e8f0;font-family:monospace">${price:.2f}</span>
        </div>
        {_st_earn_html}
        <div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px">
          <span style="padding:2px 7px;border-radius:10px;font-size:9px;font-weight:700;background:rgba(74,222,128,.1);color:#4ade80;border:1px solid rgba(74,222,128,.15)">WR ~{wr}%</span>
          <span style="padding:2px 7px;border-radius:10px;font-size:9px;font-weight:700;background:rgba(251,191,36,.1);color:#fbbf24;border:1px solid rgba(251,191,36,.15)">RS {rs}</span>
          <span style="padding:2px 7px;border-radius:10px;font-size:9px;font-weight:700;background:rgba(96,165,250,.1);color:#60a5fa;border:1px solid rgba(96,165,250,.15)">{hold}</span>
          <span style="padding:2px 7px;border-radius:10px;font-size:9px;font-weight:700;background:rgba(255,255,255,.05);color:{score_col};border:1px solid rgba(255,255,255,.08)">Score {score}</span>
        </div>
        {f'<div style="font-size:11px;color:#94a3b8;margin-bottom:8px">{detail}</div>' if detail else ''}
        <div style="display:grid;grid-template-columns:repeat(4,1fr);border:1px solid rgba(255,255,255,.06);border-radius:6px;overflow:hidden;margin-bottom:8px">
          <div style="padding:6px;text-align:center;border-right:1px solid rgba(255,255,255,.06)">
            <div style="font-size:7px;font-weight:700;color:#64748b;text-transform:uppercase;margin-bottom:2px">Stop</div>
            <div style="font-size:12px;font-weight:800;color:#ef4444;font-family:monospace">${stop:.2f}</div>
          </div>
          <div style="padding:6px;text-align:center;border-right:1px solid rgba(255,255,255,.06)">
            <div style="font-size:7px;font-weight:700;color:#64748b;text-transform:uppercase;margin-bottom:2px">Target</div>
            <div style="font-size:12px;font-weight:800;color:#4ade80;font-family:monospace">${target:.2f}</div>
          </div>
          <div style="padding:6px;text-align:center;border-right:1px solid rgba(255,255,255,.06)">
            <div style="font-size:7px;font-weight:700;color:#64748b;text-transform:uppercase;margin-bottom:2px">R:R</div>
            <div style="font-size:12px;font-weight:800;color:{rr_col}">{rr:.1f}:1</div>
          </div>
          <div style="padding:6px;text-align:center">
            <div style="font-size:7px;font-weight:700;color:#64748b;text-transform:uppercase;margin-bottom:2px">Profit</div>
            <div style="font-size:12px;font-weight:800;color:#4ade80">+${prof_d:.0f}</div>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:10px;color:#64748b">
          <span>Risk: <span style="color:#ef4444">${risk_d:.0f}</span> · {shares} shares</span>
          <span style="color:#60a5fa;cursor:pointer">Full Analysis →</span>
        </div>
      </div>
    </div>'''


def _strategy_section(icon, name, desc, wr, avg_ret, candidates_html, count, total=0):
    """Reusable strategy section wrapper with header stats."""
    est_profit = round(1000 * avg_ret / 100, 0)
    return f'''<div style="margin-bottom:24px">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;padding:0 4px">
        <div style="font-size:20px">{icon}</div>
        <div style="flex:1">
          <div style="font-size:16px;font-weight:800;color:#e2e8f0">{name}</div>
          <div style="font-size:11px;color:#64748b">{desc}</div>
        </div>
        <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">
          <span style="padding:3px 10px;border-radius:20px;font-size:10px;font-weight:700;background:rgba(74,222,128,.1);color:#4ade80;border:1px solid rgba(74,222,128,.2)">WR ~{wr}%</span>
          <span style="padding:3px 10px;border-radius:20px;font-size:10px;font-weight:700;background:rgba(96,165,250,.1);color:#60a5fa;border:1px solid rgba(96,165,250,.2)">Avg +{avg_ret}%</span>
          <span style="padding:3px 10px;border-radius:20px;font-size:10px;font-weight:700;background:rgba(251,191,36,.1);color:#fbbf24;border:1px solid rgba(251,191,36,.2)">~${est_profit:.0f}/trade</span>
          <span style="padding:3px 10px;border-radius:20px;font-size:10px;font-weight:700;background:rgba(255,255,255,.05);color:#94a3b8;border:1px solid rgba(255,255,255,.08)">{count} signals{f" / {total} total" if total else ""}</span>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;padding:0 4px">
        {candidates_html}
      </div>
    </div>'''


def _tab_strategy_signals() -> str:
    """Live strategy scanner results — all 14 strategies rendered as tiles."""
    import time as _time
    t0 = _time.time()
    sections = []

    # ── Helper to load bundle data ──
    def _load_bundle():
        if not hasattr(_load_bundle, '_data'):
            try:
                import json as _json
                from pathlib import Path as _P
                _load_bundle._data = _json.loads((_P(__file__).parent / "cache" / "last_bundle.json").read_text())
            except Exception:
                _load_bundle._data = {}
        return _load_bundle._data

    # ── Earnings warning lookup map (Task 20) ──
    _ew_map = {}
    try:
        _ew_bundle = _load_bundle()
        for _ew_r in _ew_bundle.get("all_scored", []):
            _ew_val = _ew_r.get("earnings_warning")
            if _ew_val:
                _ew_map[_ew_r["ticker"]] = _ew_val
    except Exception:
        pass

    def _get_ew(ticker):
        """Look up earnings warning for a ticker from the bundle."""
        return _ew_map.get(ticker)

    # ── Load core engine scores to prevent score mismatch ──
    _core_scores = {}
    try:
        _bnd = _load_bundle()
        for _r in _bnd.get("all_scored", []):
            _core_scores[_r["ticker"]] = _r.get("score", 0)
    except Exception:
        pass

    # ── Load core engine verdicts so every strategy tile shows BUY/WATCH/SHORT/AVOID ──
    global _CORE_VERDICTS
    _CORE_VERDICTS = {}
    try:
        _bnd2 = _load_bundle()
        for _r in _bnd2.get("all_scored", []) + _bnd2.get("killed", []):
            _v = (_r.get("decision") or {}).get("verdict")
            if _v:
                _CORE_VERDICTS[_r["ticker"]] = _v
    except Exception:
        pass

    # ── 10-Week Pullback ──
    pullback_html = ""
    try:
        from weekly_pullback import scan_weekly_pullback
        candidates = scan_weekly_pullback()
        # Only show tickers that have a core engine score (prevents mismatch)
        actionable = [c for c in candidates if c.get("trade_plan", {}).get("rr_ratio", 0) >= 1.0]
        actionable.sort(key=lambda x: x.get("trade_plan", {}).get("rr_ratio", 0), reverse=True)
        tiles = ""
        for c in actionable[:15]:
            p = c["trade_plan"]
            # Use core engine score if available, else strategy score
            _display_score = _core_scores.get(c["ticker"], c.get("score", 0))
            tiles += _strategy_tile(c["ticker"], "10-Week Pullback", c["price"],
                p.get("stop",0), p.get("target1",0), p.get("rr_ratio",0),
                c.get("rs_rank",50), _display_score, 65,
                f'50 SMA ${c["sma50"]:.2f} ({c["dist_to_50_pct"]:+.1f}%) · Slope +{c["sma50_slope_pct"]:.2f}%',
                "7-14d", earnings_warning=_get_ew(c["ticker"]))
        if tiles:
            pullback_html = _strategy_section("&#128200;", "10-Week Pullback",
                "Strong stocks pulling back to rising 50 SMA · Proven pattern (Minervini/O'Neil)",
                65, 6.5, tiles, len(actionable), len(candidates))
        else:
            pullback_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No 10-week pullback signals today</div>'
    except Exception as e:
        pullback_html = f'<div style="padding:16px;color:#f87171">10-Week Pullback error: {e}</div>'
    sections.append(pullback_html)

    # ── Mean Reversion ──
    mr_html = ""
    try:
        from mean_reversion import scan_mean_reversion
        mr_candidates = scan_mean_reversion()
        mr_actionable = [c for c in mr_candidates if c.get("trade_plan", {}).get("rr_ratio", 0) >= 1.0]
        tiles = ""
        for c in mr_actionable[:8]:
            p = c.get("trade_plan", {})
            _mr_score = _core_scores.get(c["ticker"], c.get("score", 0))
            tiles += _strategy_tile(c["ticker"], "Mean Reversion", c.get("price", p.get("entry_low", 0)),
                p.get("stop",0), p.get("target1",0), p.get("rr_ratio",0),
                c.get("rs_rank",50), _mr_score, 65,
                f'RSI {c.get("rsi",0):.0f} · Pullback {c.get("pullback_pct",0):.1f}%',
                "3-7d", earnings_warning=_get_ew(c["ticker"]))
        if tiles:
            mr_html = _strategy_section("&#128260;", "Mean Reversion",
                "Oversold bounces on strong stocks · RSI &lt; 30 or 5%+ pullback",
                65, 6.5, tiles, len(mr_actionable), len(mr_candidates))
        else:
            mr_html = f'<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No mean reversion signals ({len(mr_candidates)} below R:R threshold)</div>'
    except Exception as e:
        mr_html = f'<div style="padding:16px;color:#f87171">Mean Reversion error: {e}</div>'
    sections.append(mr_html)

    # ── Sector Rotation ──
    sr_html = ""
    try:
        from sector_rotation import scan_sector_breakouts
        breakouts = scan_sector_breakouts()
        if breakouts:
            tiles = ""
            for bk in breakouts[:8]:
                etf = bk["etf"]
                price = bk.get("price", 0) or 0
                stop = round(price * 0.97, 2) if price else 0
                target = round(price * 1.06, 2) if price else 0
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
                tiles += _strategy_tile(etf, "Sector Rotation", price, stop, target, rr,
                    50, 0, 60,
                    f'Broke 20d high &middot; Vol {bk["volume_ratio"]:.1f}x avg',
                    "7-14d", earnings_warning=_get_ew(etf))
            sr_html = _strategy_section("&#128256;", "Sector Rotation",
                "Sector ETFs breaking out on volume &middot; Ride the leaders",
                60, 5.5, tiles, len(breakouts))
        else:
            sr_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No sector breakouts detected today</div>'
    except Exception as e:
        sr_html = f'<div style="padding:20px;color:#f87171">Sector Rotation scanner error: {e}</div>'
    sections.append(sr_html)

    # ── Helper: load last_bundle.json once for bundle-based scanners ──
    _bundle_data = None
    def _load_bundle():
        nonlocal _bundle_data
        if _bundle_data is not None:
            return _bundle_data
        try:
            import json as _json
            from pathlib import Path as _Path
            _bp = _Path(__file__).parent / "cache" / "last_bundle.json"
            if _bp.exists():
                with open(_bp) as _f:
                    _bundle_data = _json.load(_f)
            else:
                _bundle_data = {}
        except Exception:
            _bundle_data = {}
        return _bundle_data

    # ── 4. VCP Scanner ──
    vcp_html = ""
    try:
        bundle = _load_bundle()
        all_scored = bundle.get("all_scored", [])
        vcp_candidates = []
        for r in all_scored:
            plan = r.get("trade_plan") or {}
            setup = (plan.get("setup_type", "") or "").lower()
            indicators = (r.get("technicals") or {}).get("indicators", {})
            is_vcp = ("vcp" in setup) or indicators.get("near_vcp", False)
            if not is_vcp:
                continue
            rr = plan.get("rr_ratio", 0) or 0
            if rr < 1.0:
                continue
            vcp_candidates.append({
                "ticker": r.get("ticker", ""),
                "price": r.get("price", 0),
                "score": r.get("score", 0),
                "rs_rank": r.get("rs_rank", 50),
                "rr": rr,
                "stop": plan.get("stop", 0),
                "target1": plan.get("target1", 0),
                "contractions": indicators.get("vcp_contractions", 0),
                "tightness": indicators.get("vcp_tightness_pct", 0),
            })
        vcp_candidates.sort(key=lambda x: x["rr"], reverse=True)

        vcp_wr = 68
        vcp_avg_ret = 8.5

        if vcp_candidates:
            tiles = ""
            for c in vcp_candidates[:10]:
                tiles += _strategy_tile(c["ticker"], "VCP Breakout", c["price"],
                    c["stop"], c["target1"], c["rr"],
                    c["rs_rank"], c["score"], vcp_wr,
                    f'{c["contractions"]} contractions &middot; Tightness {c["tightness"]:.1f}%',
                    "5-14d", earnings_warning=_get_ew(c["ticker"]))
            vcp_html = _strategy_section("&#128200;", "VCP Scanner",
                "Volatility Contraction Pattern &middot; Tightening ranges near breakout",
                vcp_wr, vcp_avg_ret, tiles, len(vcp_candidates))
        else:
            vcp_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No VCP patterns detected today</div>'
    except Exception as e:
        vcp_html = f'<div style="padding:20px;color:#f87171">VCP scanner error: {e}</div>'
    sections.append(vcp_html)

    # ── 5. Pocket Pivot Scanner ──
    pp_html = ""
    try:
        from data_archive import load_all as _da_load_all
        archive = _da_load_all()
        pp_candidates = []
        for ticker, df in archive.items():
            if df is None or len(df) < 15:
                continue
            try:
                close = df["Close"] if "Close" in df.columns else df["close"]
                volume = df["Volume"] if "Volume" in df.columns else df["volume"]
                if len(close) < 12:
                    continue
                today_close = float(close.iloc[-1])
                today_vol = float(volume.iloc[-1])
                prev_close = float(close.iloc[-2])
                if today_close <= prev_close:
                    continue
                last10_close = close.iloc[-11:-1]
                last10_vol = volume.iloc[-11:-1]
                down_mask = last10_close.diff() < 0
                if not down_mask.any():
                    continue
                max_down_vol = float(last10_vol[down_mask].max())
                if today_vol <= max_down_vol:
                    continue
                price = today_close
                stop = round(price * 0.97, 2)
                target = round(price * 1.08, 2)
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
                pp_candidates.append({
                    "ticker": ticker,
                    "price": price,
                    "volume": today_vol,
                    "max_down_vol": max_down_vol,
                    "vol_ratio": round(today_vol / max_down_vol, 1),
                    "stop": stop,
                    "target": target,
                    "rr": rr,
                })
            except Exception:
                continue
        pp_candidates.sort(key=lambda x: x["vol_ratio"], reverse=True)

        pp_wr = 62
        pp_avg_ret = 6.5

        if pp_candidates:
            tiles = ""
            for c in pp_candidates[:10]:
                tiles += _strategy_tile(c["ticker"], "Pocket Pivot", c["price"],
                    c["stop"], c["target"], c["rr"],
                    50, 0, pp_wr,
                    f'Vol {c["vol_ratio"]:.1f}x max down-day &middot; Institutional demand',
                    "5-10d", earnings_warning=_get_ew(c["ticker"]))
            pp_html = _strategy_section("&#128165;", "Pocket Pivot",
                "Volume exceeds max down-day vol in 10d &middot; Institutional demand signal",
                pp_wr, pp_avg_ret, tiles, len(pp_candidates))
        else:
            pp_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No pocket pivot signals today</div>'
    except Exception as e:
        pp_html = f'<div style="padding:20px;color:#f87171">Pocket Pivot scanner error: {e}</div>'
    sections.append(pp_html)

    # ── 6. RS New High Scanner ──
    rsnew_html = ""
    try:
        bundle = _load_bundle()
        all_scored = bundle.get("all_scored", [])
        rs_nh_candidates = []
        for r in all_scored:
            rs_rank = r.get("rs_rank", 0) or 0
            if rs_rank < 90:
                continue
            price = r.get("price", 0) or 0
            indicators = (r.get("technicals") or {}).get("indicators", {})
            high_52w = indicators.get("high_52w") or indicators.get("week52_high") or 0
            if high_52w <= 0:
                ohlcv = r.get("ohlcv", {})
                if isinstance(ohlcv, dict):
                    high_52w = ohlcv.get("high_52w", 0)
            if high_52w <= 0:
                continue
            dist_to_high = (high_52w - price) / high_52w * 100 if high_52w > 0 else 999
            if dist_to_high > 5:
                continue
            plan = r.get("trade_plan") or {}
            rr = plan.get("rr_ratio", 0) or 0
            stop = plan.get("stop", round(price * 0.97, 2))
            target = plan.get("target1", round(price * 1.10, 2))
            if rr < 1.0:
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
            rs_nh_candidates.append({
                "ticker": r.get("ticker", ""),
                "price": price,
                "rs_rank": rs_rank,
                "high_52w": high_52w,
                "dist_pct": round(dist_to_high, 1),
                "score": r.get("score", 0),
                "stop": stop,
                "target": target,
                "rr": rr,
            })
        rs_nh_candidates.sort(key=lambda x: x["rs_rank"], reverse=True)

        rsnew_wr = 66
        rsnew_avg_ret = 9.2

        if rs_nh_candidates:
            tiles = ""
            for c in rs_nh_candidates[:10]:
                tiles += _strategy_tile(c["ticker"], "RS New High", c["price"],
                    c["stop"], c["target"], c["rr"],
                    c["rs_rank"], c["score"], rsnew_wr,
                    f'52w High ${c["high_52w"]:.2f} &middot; {c["dist_pct"]:.1f}% away',
                    "7-14d", earnings_warning=_get_ew(c["ticker"]))
            rsnew_html = _strategy_section("&#127942;", "RS New High",
                "RS &ge; 90 + within 5% of 52-week high &middot; Leaders making new highs",
                rsnew_wr, rsnew_avg_ret, tiles, len(rs_nh_candidates))
        else:
            rsnew_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No RS new-high candidates today (RS &ge; 90 within 5% of 52w high)</div>'
    except Exception as e:
        rsnew_html = f'<div style="padding:20px;color:#f87171">RS New High scanner error: {e}</div>'
    sections.append(rsnew_html)

    # ── 7. Insider Buying Clusters ──
    insider_html = ""
    try:
        bundle = _load_bundle()
        all_scored = bundle.get("all_scored", [])
        insider_candidates = []
        for r in all_scored:
            ins = r.get("insider_data") or {}
            buys = ins.get("buys", 0) or 0
            if buys < 2:
                continue
            price = r.get("price", 0) or 0
            plan = r.get("trade_plan") or {}
            rr = plan.get("rr_ratio", 0) or 0
            stop = plan.get("stop", round(price * 0.95, 2))
            target = plan.get("target1", round(price * 1.12, 2))
            if rr < 1.0:
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
            insider_candidates.append({
                "ticker": r.get("ticker", ""),
                "price": price,
                "buy_count": buys,
                "sells": ins.get("sells", 0),
                "sentiment": ins.get("sentiment", "unknown"),
                "score": r.get("score", 0),
                "rs_rank": r.get("rs_rank", 50),
                "stop": stop,
                "target": target,
                "rr": rr,
            })
        insider_candidates.sort(key=lambda x: x["buy_count"], reverse=True)

        ins_wr = 64
        ins_avg_ret = 7.0

        if insider_candidates:
            tiles = ""
            for c in insider_candidates[:10]:
                tiles += _strategy_tile(c["ticker"], "Insider Cluster", c["price"],
                    c["stop"], c["target"], c["rr"],
                    c["rs_rank"], c["score"], ins_wr,
                    f'{c["buy_count"]} insider buys &middot; Sentiment: {c["sentiment"]}',
                    "14-30d", earnings_warning=_get_ew(c["ticker"]))
            insider_html = _strategy_section("&#128176;", "Insider Buying Clusters",
                "2+ insider buys in last 30 days &middot; Smart money accumulation",
                ins_wr, ins_avg_ret, tiles, len(insider_candidates))
        else:
            insider_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No insider buying clusters detected (need 2+ buys in 30 days)</div>'
    except Exception as e:
        insider_html = f'<div style="padding:20px;color:#f87171">Insider Buying scanner error: {e}</div>'
    sections.append(insider_html)

    # ── 8. Gap Holds ──
    gap_html = ""
    try:
        from data_archive import load_all as _da_load_all2
        archive2 = _da_load_all2()
        gap_candidates = []
        for ticker, df in archive2.items():
            if df is None or len(df) < 10:
                continue
            try:
                close = df["Close"] if "Close" in df.columns else df["close"]
                opens = df["Open"] if "Open" in df.columns else df["open"]
                if len(close) < 7:
                    continue
                for lookback in range(1, 6):
                    idx = -(lookback + 1)
                    if abs(idx) >= len(close):
                        continue
                    prev_close = float(close.iloc[idx])
                    gap_open = float(opens.iloc[idx + 1])
                    gap_pct = (gap_open - prev_close) / prev_close * 100 if prev_close > 0 else 0
                    if gap_pct < 3.0:
                        continue
                    current_price = float(close.iloc[-1])
                    if current_price < gap_open:
                        continue
                    stop = round(gap_open * 0.99, 2)
                    target = round(current_price * 1.08, 2)
                    rr = round((target - current_price) / (current_price - stop), 2) if current_price > stop else 0
                    gap_candidates.append({
                        "ticker": ticker,
                        "price": current_price,
                        "gap_date": f"{lookback}d ago",
                        "gap_pct": round(gap_pct, 1),
                        "gap_level": round(gap_open, 2),
                        "stop": stop,
                        "target": target,
                        "rr": rr,
                    })
                    break
            except Exception:
                continue
        gap_candidates.sort(key=lambda x: x["gap_pct"], reverse=True)

        gap_wr = 60
        gap_avg_ret = 5.8

        if gap_candidates:
            tiles = ""
            for c in gap_candidates[:10]:
                tiles += _strategy_tile(c["ticker"], "Gap Hold", c["price"],
                    c["stop"], c["target"], c["rr"],
                    50, 0, gap_wr,
                    f'Gap +{c["gap_pct"]:.1f}% ({c["gap_date"]}) &middot; Level ${c["gap_level"]:.2f}',
                    "3-7d", earnings_warning=_get_ew(c["ticker"]))
            gap_html = _strategy_section("&#9889;", "Gap Holds",
                "Gapped up 3%+ in last 5 days and holding above gap &middot; Institutional support",
                gap_wr, gap_avg_ret, tiles, len(gap_candidates))
        else:
            gap_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No gap-hold signals in last 5 days (need 3%+ gap still holding)</div>'
    except Exception as e:
        gap_html = f'<div style="padding:20px;color:#f87171">Gap Holds scanner error: {e}</div>'
    sections.append(gap_html)

    # ── 9. Short Squeeze Setup ──
    squeeze_html = ""
    try:
        bundle = _load_bundle()
        all_scored = bundle.get("all_scored", [])
        squeeze_candidates = []
        for r in all_scored:
            short_float = 0
            # Try finviz / fmp data first
            for _src_key in ("finviz", "fmp"):
                _src = r.get(_src_key) or {}
                if not isinstance(_src, dict):
                    continue
                for _sf_key in ("short_float", "Short Float", "shortFloat", "short_percent_of_float"):
                    sf_raw = _src.get(_sf_key)
                    if sf_raw is None:
                        continue
                    if isinstance(sf_raw, str):
                        try:
                            short_float = float(sf_raw.replace("%", ""))
                        except Exception:
                            pass
                    elif isinstance(sf_raw, (int, float)):
                        short_float = float(sf_raw)
                        if short_float < 1:
                            short_float *= 100
                    if short_float > 0:
                        break
                if short_float > 0:
                    break
            # Fallback: parse from fundamentals details string
            if short_float == 0:
                fund = r.get("fundamentals") or {}
                fund_det = fund.get("details", {}) if isinstance(fund, dict) else {}
                si_str = fund_det.get("short_interest", "") if isinstance(fund_det, dict) else ""
                if isinstance(si_str, str) and "%" in si_str:
                    try:
                        short_float = float(si_str.split("%")[0].strip().split()[-1])
                    except Exception:
                        pass

            if short_float < 10:
                continue
            indicators = (r.get("technicals") or {}).get("indicators", {})
            if not indicators.get("above_20ema", False):
                continue

            price = r.get("price", 0) or 0
            plan = r.get("trade_plan") or {}
            rr = plan.get("rr_ratio", 0) or 0
            stop = plan.get("stop", round(price * 0.95, 2))
            target = plan.get("target1", round(price * 1.15, 2))
            if rr < 1.0:
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
            squeeze_candidates.append({
                "ticker": r.get("ticker", ""),
                "price": price,
                "short_float": round(short_float, 1),
                "score": r.get("score", 0),
                "rs_rank": r.get("rs_rank", 50),
                "stop": stop,
                "target": target,
                "rr": rr,
            })
        squeeze_candidates.sort(key=lambda x: x["short_float"], reverse=True)

        sq_wr = 55
        sq_avg_ret = 12.0

        if squeeze_candidates:
            tiles = ""
            for c in squeeze_candidates[:10]:
                tiles += _strategy_tile(c["ticker"], "Short Squeeze", c["price"],
                    c["stop"], c["target"], c["rr"],
                    c["rs_rank"], c["score"], sq_wr,
                    f'Short float {c["short_float"]:.1f}% &middot; Above EMA20',
                    "3-10d", earnings_warning=_get_ew(c["ticker"]))
            squeeze_html = _strategy_section("&#128293;", "Short Squeeze Setup",
                "Short float &gt; 10% + price above EMA20 &middot; Squeeze potential",
                sq_wr, sq_avg_ret, tiles, len(squeeze_candidates))
        else:
            squeeze_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No short squeeze setups today (need &gt;10% short float + trending up)</div>'
    except Exception as e:
        squeeze_html = f'<div style="padding:20px;color:#f87171">Short Squeeze scanner error: {e}</div>'
    sections.append(squeeze_html)

    # ── 10. Earnings Run-Up ──
    earn_html = ""
    try:
        bundle = _load_bundle()
        all_scored = bundle.get("all_scored", [])
        earn_candidates = []
        for r in all_scored:
            earnings = r.get("earnings") or {}
            days_to = earnings.get("days_to_earnings")
            if days_to is None:
                continue
            try:
                days_to = int(days_to)
            except (ValueError, TypeError):
                continue
            if days_to < 7 or days_to > 14:
                continue
            # Check beat rate from multiple sources
            beat_rate_val = 0
            for _bk in ("eps_trend", "fmp"):
                _bsrc = r.get(_bk) or {}
                if isinstance(_bsrc, dict):
                    beat_rate_val = _bsrc.get("beat_rate", 0) or _bsrc.get("beats", 0) or 0
                    if beat_rate_val:
                        break
            if beat_rate_val == 0:
                beat_rate_val = earnings.get("beat_rate", 0) or 0
            # Normalize: if 1-4 it's a count, if >4 it's a percentage
            if isinstance(beat_rate_val, (int, float)):
                if 1 <= beat_rate_val <= 4:
                    if beat_rate_val < 3:
                        continue
                    beat_rate_val = beat_rate_val * 25
                elif beat_rate_val > 4 and beat_rate_val < 75:
                    continue

            price = r.get("price", 0) or 0
            plan = r.get("trade_plan") or {}
            rr = plan.get("rr_ratio", 0) or 0
            stop = plan.get("stop", round(price * 0.96, 2))
            target = plan.get("target1", round(price * 1.10, 2))
            if rr < 1.0:
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
            earn_candidates.append({
                "ticker": r.get("ticker", ""),
                "price": price,
                "days_to": days_to,
                "beat_rate": beat_rate_val if beat_rate_val > 4 else beat_rate_val * 25,
                "score": r.get("score", 0),
                "rs_rank": r.get("rs_rank", 50),
                "stop": stop,
                "target": target,
                "rr": rr,
            })
        earn_candidates.sort(key=lambda x: x["days_to"])

        earn_wr = 63
        earn_avg_ret = 7.5

        if earn_candidates:
            tiles = ""
            for c in earn_candidates[:10]:
                tiles += _strategy_tile(c["ticker"], "Earnings Run-Up", c["price"],
                    c["stop"], c["target"], c["rr"],
                    c["rs_rank"], c["score"], earn_wr,
                    f'Earnings in {c["days_to"]}d &middot; Beat rate {c["beat_rate"]:.0f}%',
                    "5-12d", earnings_warning=_get_ew(c["ticker"]))
            earn_html = _strategy_section("&#128197;", "Earnings Run-Up",
                "Earnings in 7-14 days + strong beat history &middot; Pre-earnings momentum play",
                earn_wr, earn_avg_ret, tiles, len(earn_candidates))
        else:
            earn_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No earnings run-up candidates (need earnings in 7-14d with 75%+ beat rate)</div>'
    except Exception as e:
        earn_html = f'<div style="padding:20px;color:#f87171">Earnings Run-Up scanner error: {e}</div>'
    sections.append(earn_html)

    # ── Golden Cross ──
    gc_html = ""
    try:
        from data_archive import load_all as _gc_load
        gc_data = _gc_load()
        gc_candidates = []
        for ticker, df in gc_data.items():
            if df is None or len(df) < 210:
                continue
            close = df["Close"].squeeze().astype(float)
            sma50 = close.rolling(50).mean()
            sma200 = close.rolling(200).mean()
            price = float(close.iloc[-1])
            if price < 2 or price > 250:
                continue
            # Golden Cross: 50 SMA crossed above 200 SMA in last 5 bars
            for i in range(-5, 0):
                if (len(sma50) > abs(i) and len(sma200) > abs(i)
                    and float(sma50.iloc[i]) > float(sma200.iloc[i])
                    and float(sma50.iloc[i-1]) <= float(sma200.iloc[i-1])):
                    stop = round(float(sma200.iloc[-1]) * 0.97, 2)
                    target = round(price * 1.08, 2)
                    rr = round((target - price) / (price - stop), 2) if price > stop else 0
                    if rr >= 1.0:
                        gc_candidates.append({"ticker": ticker, "price": price,
                            "stop": stop, "target": target, "rr": rr,
                            "sma50": round(float(sma50.iloc[-1]), 2),
                            "sma200": round(float(sma200.iloc[-1]), 2)})
                    break
        gc_candidates.sort(key=lambda x: x["rr"], reverse=True)
        tiles = ""
        for c in gc_candidates[:8]:
            tiles += _strategy_tile(c["ticker"], "Golden Cross", c["price"],
                c["stop"], c["target"], c["rr"], 50, 0, 62,
                f'50 SMA ${c["sma50"]:.2f} crossed above 200 SMA ${c["sma200"]:.2f}',
                "14-30d", earnings_warning=_get_ew(c["ticker"]))
        if tiles:
            gc_html = _strategy_section("&#10013;", "Golden Cross",
                "50 SMA crossed above 200 SMA — long-term trend reversal signal",
                62, 8.0, tiles, len(gc_candidates))
        else:
            gc_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No golden cross signals in last 5 days</div>'
    except Exception as e:
        gc_html = f'<div style="padding:16px;color:#f87171">Golden Cross error: {e}</div>'
    sections.append(gc_html)

    # ── Bull Flag ──
    bf_html = ""
    try:
        from data_archive import load_all as _bf_load
        bf_data = _bf_load()
        bf_candidates = []
        for ticker, df in bf_data.items():
            if df is None or len(df) < 30:
                continue
            close = df["Close"].squeeze().astype(float)
            high = df["High"].squeeze().astype(float)
            low = df["Low"].squeeze().astype(float)
            volume = df["Volume"].squeeze().astype(float)
            price = float(close.iloc[-1])
            if price < 2 or price > 250:
                continue
            # Impulse: 5%+ move in 3 days (bars -15 to -10)
            if len(close) < 20:
                continue
            impulse_start = float(close.iloc[-15])
            impulse_end = float(close.iloc[-10])
            impulse_pct = (impulse_end - impulse_start) / impulse_start * 100
            if impulse_pct < 5:
                continue
            # Flag: last 5 bars tight range, declining volume
            flag_range = (float(high.iloc[-5:].max()) - float(low.iloc[-5:].min())) / price * 100
            flag_vol = float(volume.iloc[-5:].mean())
            impulse_vol = float(volume.iloc[-15:-10].mean())
            if flag_range > 5 or flag_vol > impulse_vol * 0.8:
                continue
            stop = round(float(low.iloc[-5:].min()) * 0.99, 2)
            target = round(price + (impulse_end - impulse_start), 2)  # measured move
            rr = round((target - price) / (price - stop), 2) if price > stop else 0
            if rr >= 1.0:
                bf_candidates.append({"ticker": ticker, "price": price,
                    "stop": stop, "target": target, "rr": rr,
                    "impulse_pct": round(impulse_pct, 1),
                    "flag_range": round(flag_range, 1)})
        bf_candidates.sort(key=lambda x: x["rr"], reverse=True)
        tiles = ""
        for c in bf_candidates[:8]:
            tiles += _strategy_tile(c["ticker"], "Bull Flag", c["price"],
                c["stop"], c["target"], c["rr"], 50, 0, 65,
                f'Impulse +{c["impulse_pct"]}% \u2192 Flag range {c["flag_range"]}%',
                "5-10d", earnings_warning=_get_ew(c["ticker"]))
        if tiles:
            bf_html = _strategy_section("\U0001f6a9", "Bull Flag",
                "Strong impulse \u2192 tight consolidation with declining volume \u2192 breakout",
                65, 7.5, tiles, len(bf_candidates))
        else:
            bf_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No bull flag setups detected</div>'
    except Exception as e:
        bf_html = f'<div style="padding:16px;color:#f87171">Bull Flag error: {e}</div>'
    sections.append(bf_html)

    # ── Volume Breakout ──
    vb_html = ""
    try:
        from data_archive import load_all as _vb_load
        vb_data = _vb_load()
        vb_candidates = []
        for ticker, df in vb_data.items():
            if df is None or len(df) < 25:
                continue
            close = df["Close"].squeeze().astype(float)
            high = df["High"].squeeze().astype(float)
            volume = df["Volume"].squeeze().astype(float)
            price = float(close.iloc[-1])
            if price < 2 or price > 250:
                continue
            high_20 = float(high.iloc[-21:-1].max())
            vol_avg = float(volume.iloc[-20:].mean())
            vol_today = float(volume.iloc[-1])
            # Breakout: price above 20-day high AND volume >= 2x average
            if price > high_20 and vol_today >= vol_avg * 2.0:
                stop = round(high_20 * 0.98, 2)
                target = round(price * 1.08, 2)
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
                vol_ratio = round(vol_today / vol_avg, 1) if vol_avg > 0 else 0
                if rr >= 0.5:
                    vb_candidates.append({"ticker": ticker, "price": price,
                        "stop": stop, "target": target, "rr": rr,
                        "vol_ratio": vol_ratio, "high_20": round(high_20, 2)})
        vb_candidates.sort(key=lambda x: x["vol_ratio"], reverse=True)
        tiles = ""
        for c in vb_candidates[:8]:
            tiles += _strategy_tile(c["ticker"], "Volume Breakout", c["price"],
                c["stop"], c["target"], c["rr"], 50, 0, 60,
                f'Broke ${c["high_20"]:.2f} (20d high) on {c["vol_ratio"]}x volume',
                "5-10d", earnings_warning=_get_ew(c["ticker"]))
        if tiles:
            vb_html = _strategy_section("&#128202;", "Volume Breakout",
                "Price breaking 20-day high on 2x+ average volume \u2014 institutional participation",
                60, 5.8, tiles, len(vb_candidates))
        else:
            vb_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No volume breakout signals today</div>'
    except Exception as e:
        vb_html = f'<div style="padding:16px;color:#f87171">Volume Breakout error: {e}</div>'
    sections.append(vb_html)

    # ── VWAP Reclaim ──
    vr_html = ""
    try:
        from data_archive import load_all as _vr_load
        vr_data = _vr_load()
        vr_candidates = []
        for ticker, df in vr_data.items():
            if df is None or len(df) < 20:
                continue
            if "VWAP" not in df.columns:
                continue
            close = df["Close"].squeeze().astype(float)
            low = df["Low"].squeeze().astype(float)
            vwap = df["VWAP"].squeeze().astype(float)
            price = float(close.iloc[-1])
            vwap_now = float(vwap.iloc[-1])
            if price < 2 or price > 250 or vwap_now <= 0:
                continue
            # Reclaim: yesterday low was below VWAP, today close is above
            if len(low) >= 2 and float(low.iloc[-2]) < float(vwap.iloc[-2]) and price > vwap_now:
                stop = round(vwap_now * 0.98, 2)
                target = round(price * 1.05, 2)
                rr = round((target - price) / (price - stop), 2) if price > stop else 0
                if rr >= 0.5:
                    dist = round((price - vwap_now) / vwap_now * 100, 2)
                    vr_candidates.append({"ticker": ticker, "price": price,
                        "stop": stop, "target": target, "rr": rr,
                        "vwap": round(vwap_now, 2), "dist": dist})
        vr_candidates.sort(key=lambda x: x["rr"], reverse=True)
        tiles = ""
        for c in vr_candidates[:8]:
            tiles += _strategy_tile(c["ticker"], "VWAP Reclaim", c["price"],
                c["stop"], c["target"], c["rr"], 50, 0, 58,
                f'Reclaimed VWAP ${c["vwap"]:.2f} ({c["dist"]:+.1f}% above)',
                "3-5d", earnings_warning=_get_ew(c["ticker"]))
        if tiles:
            vr_html = _strategy_section("&#128205;", "VWAP Reclaim",
                "Price reclaimed VWAP after dipping below \u2014 institutional demand confirmed",
                58, 4.5, tiles, len(vr_candidates))
        else:
            vr_html = '<div style="padding:16px;color:#64748b;text-align:center;font-size:13px">No VWAP reclaim signals today</div>'
    except Exception as e:
        vr_html = f'<div style="padding:16px;color:#f87171">VWAP Reclaim error: {e}</div>'
    sections.append(vr_html)

    elapsed = _time.time() - t0
    header = f'''<div style="padding:20px 24px;background:linear-gradient(135deg,rgba(30,41,59,.7),rgba(15,23,42,.9));border:1px solid rgba(255,255,255,.06);border-radius:12px;margin-bottom:20px">
      <div style="display:flex;align-items:center;gap:14px">
        <div style="font-size:28px">&#128640;</div>
        <div>
          <div style="font-size:18px;font-weight:800;color:#e2e8f0">Strategy Signals</div>
          <div style="font-size:13px;color:#94a3b8">14 strategies scanned &middot; Click any ticker to open full analysis &middot; Scanned in {elapsed:.1f}s</div>
        </div>
      </div>
    </div>'''

    return header + "".join(sections)


