def _tab_account_profiles() -> str:
    """Account Profiles — position sizing and strategy access by equity level."""
    PROFILES = [
        ("Starter",       "$1K-$3K",    2,  "40%", "2%",   "Core + Pullback",          "#94a3b8"),
        ("Growth",        "$3K-$10K",   4,  "25%", "1.5%", "+ Mean Reversion",         "#3b82f6"),
        ("Active",        "$10K-$25K",  6,  "15%", "1%",   "All Strategies",           "#8b5cf6"),
        ("Standard",      "$25K-$50K",  8,  "12%", "1%",   "All + Shorts",             "#059669"),
        ("Professional",  "$50K-$100K", 10, "10%", "1%",   "All + Shorts",             "#f59e0b"),
        ("Premium",       "$100K-$1M",  15, "7%",  "0.5%", "All + Shorts",             "#dc2626"),
    ]

    rows = ""
    for name, equity, positions, per_trade, risk, strategies, color in PROFILES:
        rows += f'''
        <tr style="border-bottom:1px solid var(--border)">
          <td style="padding:12px 14px;font-weight:700;color:{color}">{name}</td>
          <td style="padding:12px 14px;font-weight:600">{equity}</td>
          <td style="padding:12px 14px;text-align:center;font-weight:700">{positions}</td>
          <td style="padding:12px 14px;text-align:center">{per_trade}</td>
          <td style="padding:12px 14px;text-align:center;font-weight:700;color:#dc2626">{risk}</td>
          <td style="padding:12px 14px;font-size:12px;color:var(--text-muted)">{strategies}</td>
        </tr>'''

    return f'''
    <div style="padding:20px 24px;max-width:1000px;margin:0 auto">
      <div style="background:linear-gradient(135deg,rgba(139,92,246,0.12),rgba(139,92,246,0.06));
                  border:1px solid rgba(139,92,246,0.35);border-radius:12px;padding:18px 22px;margin-bottom:24px">
        <div style="font-size:20px;font-weight:800;color:#7c3aed">&#128176; Account Profiles</div>
        <div style="font-size:13px;color:#8b5cf6;margin-top:6px">
          Position sizing and strategy access scale with account equity.
          Smaller accounts concentrate on fewer, higher-conviction strategies.
        </div>
      </div>
      <div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;overflow:hidden">
        <table style="width:100%;border-collapse:collapse;font-size:13px">
          <thead>
            <tr style="background:var(--surface-alt)">
              <th style="padding:12px 14px;text-align:left;font-weight:700;border-bottom:2px solid var(--border)">Profile</th>
              <th style="padding:12px 14px;text-align:left;font-weight:700;border-bottom:2px solid var(--border)">Equity</th>
              <th style="padding:12px 14px;text-align:center;font-weight:700;border-bottom:2px solid var(--border)">Max Positions</th>
              <th style="padding:12px 14px;text-align:center;font-weight:700;border-bottom:2px solid var(--border)">Per Trade</th>
              <th style="padding:12px 14px;text-align:center;font-weight:700;border-bottom:2px solid var(--border)">Risk/Trade</th>
              <th style="padding:12px 14px;text-align:left;font-weight:700;border-bottom:2px solid var(--border)">Strategies</th>
            </tr>
          </thead>
          <tbody>
            {rows}
          </tbody>
        </table>
      </div>
      <div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;
                  padding:16px 20px;margin-top:16px">
        <div style="font-size:13px;font-weight:700;color:var(--text);margin-bottom:8px">Key Notes</div>
        <div style="font-size:12px;color:var(--text-muted);line-height:1.8">
          &#8226; <strong>Per Trade %</strong> = maximum allocation of total equity to a single position<br>
          &#8226; <strong>Risk/Trade %</strong> = maximum loss allowed per position (determines stop placement)<br>
          &#8226; Smaller accounts should NOT try to run all 14 strategies &mdash; focus on Core + Pullback first<br>
          &#8226; Short selling requires a margin account (min $25K for PDT rule compliance)<br>
          &#8226; All profiles use the same scoring engine &mdash; only sizing and strategy access differ
        </div>
      </div>
    </div>'''


# ─────────────────────────────────────────────────────────────────────────────
