# ─────────────────────────────────────────────────────────────────────────────
#  ZACKS LIVE RAW TAB
# ─────────────────────────────────────────────────────────────────────────────

def _tab_zacks_raw(buy_list: list, r1_scores: dict, sell_list: list, top_movers: list,
                   scored_map: dict | None = None) -> str:
    """Zacks Intel tab — server-side pre-rendered tables. No JS needed to display rows."""


    scored_map   = scored_map or {}
    buy_count    = len(buy_list)
    sell_count   = len(sell_list)
    movers_count = len(top_movers)

    # ── colour helpers ────────────────────────────────────────────────────────
    def sc_color(s):
        return "#059669" if s >= 75 else "#d97706" if s >= 55 else "#dc2626"
    def rr_color(rr):
        return "#059669" if rr >= 3 else "#d97706" if rr >= 2 else "#dc2626"
    def grade_color(g):
        if not g or g == "—": return "#94a3b8"
        return {"A": "#059669", "B": "#16a34a", "C": "#d97706",
                "D": "#dc2626", "F": "#dc2626"}.get(g[0].upper(), "#94a3b8")
    def grade_badge(g):
        g = g or "—"
        c = grade_color(g)
        return f'<span style="font-size:11px;font-weight:700;padding:1px 6px;border-radius:4px;background:{c}18;color:{c}">{g}</span>'
    def verdict_badge(v):
        vc  = {"BUY": "#059669", "WATCH": "#d97706", "SHORT": "#7c3aed", "AVOID": "#dc2626"}.get(v, "#64748b")
        vbg = {"BUY": "#d1fae5", "WATCH": "#fef3c7", "SHORT": "#ede9fe", "AVOID": "#fee2e2"}.get(v, "#f1f5f9")
        return f'<span style="font-size:11px;font-weight:700;padding:2px 8px;border-radius:5px;background:{vbg};color:{vc}">{v}</span>'
    def row_click(tk):
        return f'onclick="spOpen(\'{tk}\')" style="cursor:pointer" onmouseover="this.style.background=\'var(--surface-alt)\'" onmouseout="this.style.background=\'\'"'

    # ── BUY LIST rows ─────────────────────────────────────────────────────────
    buy_rows = []
    for tk in buy_list:
        sc   = r1_scores.get(tk, {})
        sd   = scored_map.get(tk, {})
        price = sd.get("price", 0)
        score = sd.get("score", 0)
        plan  = sd.get("trade_plan", {}) or {}
        rr    = plan.get("rr_ratio", 0) or 0
        verd  = sd.get("decision", {}) or {}
        verdict = verd.get("verdict", "—") if isinstance(verd, dict) else "—"
        name  = (sd.get("name") or tk)[:30]
        sector= (sd.get("sector") or "—")[:20]
        vgm   = sc.get("vgm", "—") or "—"
        val   = sc.get("value", "—") or "—"
        gro   = sc.get("growth", "—") or "—"
        mom   = sc.get("momentum", "—") or "—"
        sc_col = sc_color(score) if score else "#94a3b8"
        rr_col = rr_color(rr) if rr else "#94a3b8"
        buy_rows.append(
            f'<tr {row_click(tk)}>'
            f'<td class="zr-td" style="font-weight:700;color:var(--primary)">{tk}</td>'
            f'<td class="zr-td" style="font-size:12px;color:var(--text-muted)">{name}</td>'
            f'<td class="zr-td" style="text-align:right;font-weight:600">'
            f'{"${:.2f}".format(price) if price else "—"}</td>'
            f'<td class="zr-td" style="text-align:center;font-weight:700;color:{sc_col}">'
            f'{"{}".format(int(score)) if score else "—"}</td>'
            f'<td class="zr-td" style="text-align:center;font-weight:700;color:{rr_col}">'
            f'{"{:.1f}:1".format(rr) if rr else "—"}</td>'
            f'<td class="zr-td" style="font-size:12px;color:var(--text-muted)">{sector}</td>'
            f'<td class="zr-td" style="text-align:center">'
            f'{verdict_badge(verdict) if verdict not in ("—","") else "—"}</td>'
            f'<td class="zr-td" style="text-align:center">{grade_badge(vgm)}</td>'
            f'<td class="zr-td" style="text-align:center">{grade_badge(val)}</td>'
            f'<td class="zr-td" style="text-align:center">{grade_badge(gro)}</td>'
            f'<td class="zr-td" style="text-align:center">{grade_badge(mom)}</td>'
            f'</tr>'
        )
    buy_rows_html = "\n".join(buy_rows) or '<tr><td colspan="11" style="padding:20px;text-align:center;color:var(--text-muted)">No data</td></tr>'

    # ── SELL LIST rows ────────────────────────────────────────────────────────
    sell_rows = []
    for item in sell_list:
        tk  = (item.get("ticker") or item) if isinstance(item, dict) else str(item)
        co  = (item.get("company") or "—")[:35] if isinstance(item, dict) else "—"
        sd   = scored_map.get(tk, {})
        price = sd.get("price", 0)
        score = sd.get("score", 0)
        verd  = sd.get("decision", {}) or {}
        verdict = verd.get("verdict", "—") if isinstance(verd, dict) else "—"
        bs    = (sd.get("bear_setup") or {}).get("score", 0) or 0
        sc_col = sc_color(score) if score else "#94a3b8"
        bs_col = "#dc2626" if bs >= 12 else "#d97706" if bs >= 8 else "#94a3b8"
        sell_rows.append(
            f'<tr {row_click(tk)}>'
            f'<td class="zr-td" style="font-weight:700;color:#dc2626">{tk}</td>'
            f'<td class="zr-td" style="font-size:12px;color:var(--text-muted)">{co}</td>'
            f'<td class="zr-td" style="text-align:right;font-weight:600">'
            f'{"${:.2f}".format(price) if price else "—"}</td>'
            f'<td class="zr-td" style="text-align:center;font-weight:700;color:{sc_col}">'
            f'{"{}".format(int(score)) if score else "—"}</td>'
            f'<td class="zr-td" style="text-align:center">'
            f'{verdict_badge(verdict) if verdict not in ("—","") else "—"}</td>'
            f'<td class="zr-td" style="text-align:center;font-weight:700;color:{bs_col}">'
            f'{bs if bs else "—"}</td>'
            f'</tr>'
        )
    sell_rows_html = "\n".join(sell_rows) or '<tr><td colspan="6" style="padding:20px;text-align:center;color:var(--text-muted)">No data</td></tr>'

    # ── TOP MOVERS rows ───────────────────────────────────────────────────────
    movers_rows = []
    for m in top_movers:
        tk   = m.get("ticker") or m.get("sym") or ""
        if not tk:
            continue
        co   = (m.get("company") or "—")[:30]
        ttype = m.get("type") or m.get("trade_type") or "Long"
        date = m.get("date_added") or "—"
        p_add = m.get("price_add") or "—"
        p_last = m.get("price_last") or "—"
        pct  = m.get("pct_chg") or "—"
        svc  = (m.get("service") or "—")[:30]
        type_col = "#dc2626" if "short" in ttype.lower() else "#059669"
        try:
            pct_f = float(str(pct).replace("%", "").replace("+", ""))
            pct_col = "#059669" if pct_f > 0 else "#dc2626"
        except Exception:
            pct_col = "#94a3b8"
        movers_rows.append(
            f'<tr {row_click(tk)}>'
            f'<td class="zr-td" style="font-weight:700;color:var(--primary)">{tk}</td>'
            f'<td class="zr-td" style="font-size:12px;color:var(--text-muted)">{co}</td>'
            f'<td class="zr-td" style="text-align:center;font-weight:700;color:{type_col}">{ttype}</td>'
            f'<td class="zr-td" style="text-align:center;font-size:12px;color:var(--text-muted)">{date}</td>'
            f'<td class="zr-td" style="text-align:right;font-size:12px">{p_add}</td>'
            f'<td class="zr-td" style="text-align:right;font-size:12px">{p_last}</td>'
            f'<td class="zr-td" style="text-align:right;font-weight:700;color:{pct_col}">{pct}</td>'
            f'<td class="zr-td" style="font-size:11px;color:var(--text-muted)">{svc}</td>'
            f'</tr>'
        )
    movers_rows_html = "\n".join(movers_rows) or '<tr><td colspan="8" style="padding:20px;text-align:center;color:var(--text-muted)">No data</td></tr>'

    # ── Table header helpers ──────────────────────────────────────────────────
    def th(label, align="left"):
        return f'<th class="zr-th" style="text-align:{align}">{label}</th>'

    buy_hdr = "".join([th("Ticker"), th("Name"), th("Price","right"), th("Score","center"),
                       th("R:R","center"), th("Sector"), th("Verdict","center"),
                       th("VGM","center"), th("Value","center"), th("Growth","center"), th("Mom","center")])
    sell_hdr = "".join([th("Ticker"), th("Company"), th("Price","right"),
                        th("Score","center"), th("Verdict","center"), th("Bear Score","center")])
    movers_hdr = "".join([th("Ticker"), th("Company"), th("Type","center"), th("Added","center"),
                          th("Price Add","right"), th("Price Now","right"), th("% Chg","right"), th("Service")])

    return f"""
<div style="padding:20px">
<style>
.zr-pill{{padding:8px 18px;border-radius:20px;font-size:13px;font-weight:700;
  border:1.5px solid var(--border);cursor:pointer;background:var(--surface);
  color:var(--text-muted);transition:all .15s}}
.zr-pill:hover{{opacity:.8}}
.zr-pill-on{{background:#1e293b!important;color:white!important;border-color:var(--text)!important}}
.zr-tbl{{width:100%;border-collapse:collapse;font-size:13px}}
.zr-th{{padding:10px 14px;font-size:11px;font-weight:700;color:var(--text-muted);
  text-transform:uppercase;letter-spacing:.5px;white-space:nowrap;
  background:var(--surface-alt);border-bottom:2px solid var(--border)}}
.zr-td{{padding:9px 14px;border-bottom:1px solid var(--border)}}
</style>

<div style="display:flex;gap:6px;margin-bottom:20px;flex-wrap:wrap">
  <button class="zr-pill zr-pill-on" onclick="zrShow('zr-p-buy',this)">
    &#9733; Buy List
    <span style="margin-left:4px;background:rgba(34,197,94,0.15);color:#4ade80;padding:1px 7px;border-radius:10px;font-size:11px">{buy_count}</span>
  </button>
  <button class="zr-pill" onclick="zrShow('zr-p-sell',this)">
    &#128683; Sell List
    <span style="margin-left:4px;background:rgba(239,68,68,0.15);color:#f87171;padding:1px 7px;border-radius:10px;font-size:11px">{sell_count}</span>
  </button>
  <button class="zr-pill" onclick="zrShow('zr-p-movers',this)">
    &#128200; Top Movers 30d
    <span style="margin-left:4px;background:rgba(59,130,246,0.15);color:#60a5fa;padding:1px 7px;border-radius:10px;font-size:11px">{movers_count}</span>
  </button>
</div>

<div id="zr-p-buy">
  <div style="overflow-x:auto">
  <table class="zr-tbl">
    <thead><tr>{buy_hdr}</tr></thead>
    <tbody>{buy_rows_html}</tbody>
  </table>
  </div>
</div>

<div id="zr-p-sell" style="display:none">
  <div style="overflow-x:auto">
  <table class="zr-tbl">
    <thead><tr>{sell_hdr}</tr></thead>
    <tbody>{sell_rows_html}</tbody>
  </table>
  </div>
</div>

<div id="zr-p-movers" style="display:none">
  <div style="overflow-x:auto">
  <table class="zr-tbl">
    <thead><tr>{movers_hdr}</tr></thead>
    <tbody>{movers_rows_html}</tbody>
  </table>
  </div>
</div>
</div>

<script>
function zrShow(id, btn) {{
  ['zr-p-buy','zr-p-sell','zr-p-movers'].forEach(function(p) {{
    document.getElementById(p).style.display = (p === id) ? '' : 'none';
  }});
  document.querySelectorAll('.zr-pill').forEach(function(b) {{
    b.classList.remove('zr-pill-on');
  }});
  if (btn) btn.classList.add('zr-pill-on');
}}
</script>"""


# ─────────────────────────────────────────────────────────────────────────────
#  INDEX STOCKS TAB (S&P 500 / Russell 1000)
# ─────────────────────────────────────────────────────────────────────────────

def _tab_index_stocks(all_scored: list, killed: list, index_list: list,
                      index_name: str, price_label: str,
                      tier_100: dict | None = None, tier_250: dict | None = None) -> str:
    """Show Top BUY & SELL for <$100 and <$250 tiers, plus full scored table."""
    if not index_list:
        return f"""
        <div style="padding:40px;text-align:center;color:var(--text-muted)">
          <div style="font-size:32px;margin-bottom:12px">&#128202;</div>
          <div style="font-size:16px;font-weight:600;margin-bottom:8px">Run the scan first — {index_name} data not yet loaded</div>
          <div style="font-size:13px">The index constituent list is fetched on each daily scan</div>
        </div>"""

    tier_100 = tier_100 or {}
    tier_250 = tier_250 or {}

    # Unique prefix for HTML IDs (avoid collision when tab is rendered twice)
    pfx = index_name.lower().replace(" ", "").replace("&", "")[:6]  # "sp500" or "russel"

    index_set = {t.upper() for t in index_list}
    all_combined = all_scored + killed
    in_index = [r for r in all_combined if r.get("ticker", "").upper() in index_set]

    total_in_index = len(index_set)
    scored_count   = len(in_index)

    VERDICT_COLORS = {"BUY": "#4ade80", "WATCH": "#fbbf24", "SHORT": "#c084fc", "AVOID": "#f87171"}
    VERDICT_BGS    = {"BUY": "rgba(34,197,94,0.15)", "WATCH": "rgba(245,158,11,0.15)", "SHORT": "rgba(168,85,247,0.15)", "AVOID": "rgba(239,68,68,0.15)"}
    TH = ('style="padding:10px 14px;text-align:{align};font-size:11px;font-weight:700;'
          'color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px"')

    def _render_row(r):
        ticker  = r.get("ticker", "")
        name    = r.get("name", ticker)[:28]
        price   = r.get("price", 0)
        score   = r.get("score", 0)
        plan    = r.get("trade_plan", {})
        rr      = plan.get("rr_ratio", 0)
        setup   = plan.get("setup_type", "—")[:30]
        verdict = r.get("decision", {}).get("verdict", "—")
        sector  = r.get("sector", "—")[:20]
        bear_sc = r.get("bear_setup", {}).get("score", 0)
        vc  = VERDICT_COLORS.get(verdict, "#64748b")
        vbg = VERDICT_BGS.get(verdict, "rgba(100,116,139,0.12)")
        sc_c = "#059669" if score >= 75 else "#d97706" if score >= 55 else "#dc2626"
        rr_c = "#059669" if rr >= 3 else "#d97706" if rr >= 2 else "#dc2626"
        extra = f'Bear {bear_sc}/15' if verdict in ("SHORT", "AVOID") and bear_sc else setup
        return (
            f'<tr style="border-bottom:1px solid var(--border);cursor:pointer" '
            f'onclick="spOpen(\'{ticker}\')" '
            f'onmouseover="this.style.background=\'var(--surface-alt)\'" '
            f'onmouseout="this.style.background=\'\'">'
            f'<td style="padding:9px 14px;font-weight:700;color:var(--primary)">{ticker}</td>'
            f'<td style="padding:9px 14px;font-size:12px;color:var(--text-muted)">{name}</td>'
            f'<td style="padding:9px 14px;text-align:right;font-weight:600">${price:.2f}</td>'
            f'<td style="padding:9px 14px;text-align:center;font-weight:700;color:{sc_c}">{score:.0f}</td>'
            f'<td style="padding:9px 14px;text-align:center;font-size:12px;color:{rr_c}">{rr:.1f}:1</td>'
            f'<td style="padding:9px 14px;font-size:12px;color:var(--text-muted)">{sector}</td>'
            f'<td style="padding:9px 14px;font-size:12px;color:var(--text-muted)">{extra}</td>'
            f'<td style="padding:9px 14px;text-align:center">'
            f'<span style="font-size:11px;font-weight:700;padding:2px 8px;border-radius:5px;background:{vbg};color:{vc}">{verdict}</span>'
            f'</td></tr>'
        )

    def _empty_row(msg, cols=8):
        return f'<tr><td colspan="{cols}" style="padding:20px;text-align:center;color:var(--text-muted);font-style:italic">{msg}</td></tr>'

    def _picks_table(picks, accent_color):
        if not picks:
            return _empty_row("No picks in this tier")
        return "".join(_render_row(r) for r in picks)

    table_hdr = """<tr style="background:var(--surface-alt);border-bottom:2px solid var(--border)">
      <th style="padding:10px 14px;text-align:left;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">Ticker</th>
      <th style="padding:10px 14px;text-align:left;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">Name</th>
      <th style="padding:10px 14px;text-align:right;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">Price</th>
      <th style="padding:10px 14px;text-align:center;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">Score</th>
      <th style="padding:10px 14px;text-align:center;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">R:R</th>
      <th style="padding:10px 14px;text-align:left;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">Sector</th>
      <th style="padding:10px 14px;text-align:left;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">Setup</th>
      <th style="padding:10px 14px;text-align:center;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px">Verdict</th>
    </tr>"""

    def _tier_section(label, price_cap, buys, sells, accent, sell_accent):
        buy_count  = len(buys)
        sell_count = len(sells)
        return f"""
        <div class="idx-tier">
          <div class="idx-tier-header">{label}</div>
          <div class="idx-tier-grid">
            <div class="idx-tier-half">
              <div class="idx-tier-label" style="color:{accent}">
                <span style="font-size:16px">&#9650;</span> Top BUY
                <span class="idx-tier-count" style="background:{accent}22;color:{accent}">{buy_count}</span>
              </div>
              <div style="overflow-x:auto">
                <table style="width:100%;border-collapse:collapse;font-size:13px">
                  <thead>{table_hdr}</thead>
                  <tbody>{_picks_table(buys, accent)}</tbody>
                </table>
              </div>
            </div>
            <div class="idx-tier-half">
              <div class="idx-tier-label" style="color:{sell_accent}">
                <span style="font-size:16px">&#9660;</span> Top SELL / SHORT
                <span class="idx-tier-count" style="background:{sell_accent}22;color:{sell_accent}">{sell_count}</span>
              </div>
              <div style="overflow-x:auto">
                <table style="width:100%;border-collapse:collapse;font-size:13px">
                  <thead>{table_hdr}</thead>
                  <tbody>{_picks_table(sells, sell_accent)}</tbody>
                </table>
              </div>
            </div>
          </div>
        </div>"""

    # Build the two tier sections
    section_100 = _tier_section(
        f"Under $100", 100,
        tier_100.get("buy", []), tier_100.get("sell", []),
        "#059669", "#dc2626",
    )
    section_250 = _tier_section(
        f"Under $250", 250,
        tier_250.get("buy", []), tier_250.get("sell", []),
        "#0ea5e9", "#7c3aed",
    )

    # Serialize full-universe for JS sort/filter
    import json as _json
    idx_rows = []
    for r in in_index:
        plan    = r.get("trade_plan", {})
        verdict = r.get("decision", {}).get("verdict", "—")
        idx_rows.append({
            "ticker":  r.get("ticker", ""),
            "name":    r.get("name", r.get("ticker", ""))[:28],
            "price":   round(r.get("price", 0), 2),
            "score":   round(r.get("score", 0), 1),
            "rr":      round(plan.get("rr_ratio", 0), 2),
            "sector":  r.get("sector", "—")[:20],
            "setup":   plan.get("setup_type", "—")[:30],
            "verdict": verdict,
        })
    idx_json = _json.dumps(idx_rows)

    # verdict counts for pills
    cnt_buy   = sum(1 for r in idx_rows if r["verdict"] == "BUY")
    cnt_watch = sum(1 for r in idx_rows if r["verdict"] == "WATCH")
    cnt_avoid = sum(1 for r in idx_rows if r["verdict"] == "AVOID")
    cnt_short = sum(1 for r in idx_rows if r["verdict"] == "SHORT")

    return f"""
<style>
.idx-tier {{
  margin-bottom:28px;
}}
.idx-tier-header {{
  font-size:18px;font-weight:800;color:var(--text);margin-bottom:14px;
  padding:10px 16px;background:var(--surface);border:1px solid var(--border);
  border-radius:var(--radius);
}}
.idx-tier-grid {{
  display:grid;grid-template-columns:1fr 1fr;gap:20px;
}}
@media(max-width:960px) {{
  .idx-tier-grid {{ grid-template-columns:1fr; }}
}}
.idx-tier-half {{
  background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);
  overflow:hidden;
}}
.idx-tier-label {{
  display:flex;align-items:center;gap:8px;padding:12px 16px;font-size:14px;
  font-weight:700;border-bottom:2px solid var(--border);
}}
.idx-tier-count {{
  font-size:11px;padding:1px 8px;border-radius:10px;font-weight:700;
}}
.idx-full-toggle {{
  display:flex;align-items:center;gap:8px;padding:10px 16px;margin-top:8px;
  background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);
  cursor:pointer;font-size:13px;font-weight:600;color:var(--text-muted);
}}
.idx-full-toggle:hover {{ background:var(--surface-alt); }}
.idx-pill {{
  padding:5px 13px;border-radius:20px;font-size:12px;font-weight:600;
  border:1.5px solid var(--border);background:var(--surface);color:var(--text-muted);
  cursor:pointer;transition:all .15s;
}}
.idx-pill:hover {{ opacity:.8; }}
.idx-pill.active {{ background:#1e293b;color:#fff;border-color:var(--text); }}
.idx-th {{
  padding:9px 12px;text-align:left;font-size:11px;font-weight:700;color:var(--text-muted);
  text-transform:uppercase;letter-spacing:.4px;cursor:pointer;user-select:none;white-space:nowrap;
}}
.idx-th:hover {{ color:var(--text); }}
.idx-td {{ padding:8px 12px;font-size:13px;border-bottom:1px solid var(--border); }}
</style>

<div style="padding:20px">
  <div style="display:flex;flex-wrap:wrap;gap:12px;margin-bottom:24px;padding:14px 16px;
    background:var(--surface);border:1px solid var(--border);border-radius:var(--radius)">
    <div style="font-size:13px;color:var(--text-muted)">
      <strong style="color:var(--text)">{total_in_index:,}</strong> stocks in {index_name}
    </div>
    <div style="font-size:13px;color:var(--text-muted)">
      <strong style="color:var(--primary)">{scored_count}</strong> scored in our universe
    </div>
    <div style="font-size:13px;color:var(--text-muted);margin-left:auto">
      No Zacks conditioning &mdash; full index scan
    </div>
  </div>

  {section_100}
  {section_250}

  <div class="idx-full-toggle" id="{pfx}-full-toggle"
       onclick="{pfx}Toggle()">
    <span id="{pfx}-toggle-chevron">&#9654;</span>
    <span id="{pfx}-toggle-label">Show all {scored_count} scored {index_name} stocks</span>
  </div>
  <div id="{pfx}-full-panel" style="display:none;margin-top:12px">
    <div style="display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:10px">
      <button class="{pfx}-pill active" onclick="{pfx}SetFilter(this,'ALL')">All ({scored_count})</button>
      <button class="{pfx}-pill" onclick="{pfx}SetFilter(this,'BUY')"
        style="border-color:rgba(34,197,94,.5);color:#4ade80">&#9679; BUY ({cnt_buy})</button>
      <button class="{pfx}-pill" onclick="{pfx}SetFilter(this,'WATCH')"
        style="border-color:rgba(245,158,11,.5);color:#fbbf24">WATCH ({cnt_watch})</button>
      <button class="{pfx}-pill" onclick="{pfx}SetFilter(this,'SHORT')"
        style="border-color:rgba(168,85,247,.5);color:#c084fc">SHORT ({cnt_short})</button>
      <button class="{pfx}-pill" onclick="{pfx}SetFilter(this,'AVOID')"
        style="border-color:rgba(239,68,68,.5);color:#f87171">AVOID ({cnt_avoid})</button>
      <div style="flex:1"></div>
      <input id="{pfx}-search" placeholder="&#128269; Search ticker / sector…"
        oninput="{pfx}Render()"
        style="font-size:12px;border:1.5px solid var(--border);border-radius:8px;
               padding:5px 10px;background:var(--surface);color:var(--text);outline:none;width:200px">
      <span style="font-size:11px;color:var(--text-muted)">Sort:</span>
      <select id="{pfx}-sort-sel" onchange="{pfx}Render()"
        style="font-size:12px;border:1.5px solid var(--border);border-radius:8px;padding:5px 10px;
               background:var(--surface);color:var(--text);cursor:pointer;outline:none">
        <option value="score">Score ↓</option>
        <option value="rr">R:R ↓</option>
        <option value="price">Price ↓</option>
        <option value="alpha">Ticker A–Z</option>
        <option value="sector">Sector A–Z</option>
      </select>
    </div>
    <div id="{pfx}-count" style="font-size:11px;color:var(--text-muted);margin-bottom:6px;text-align:right"></div>
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;overflow-x:auto">
      <table style="width:100%;border-collapse:collapse;font-size:13px;min-width:800px">
        <thead>
          <tr style="background:var(--surface-alt);border-bottom:2px solid var(--border)">
            <th class="idx-th" onclick="{pfx}SortBy('alpha')">Ticker</th>
            <th class="idx-th" onclick="{pfx}SortBy('alpha')">Name</th>
            <th class="idx-th" onclick="{pfx}SortBy('price')" style="text-align:right">Price</th>
            <th class="idx-th" onclick="{pfx}SortBy('score')" style="text-align:center">Score &#9660;</th>
            <th class="idx-th" onclick="{pfx}SortBy('rr')" style="text-align:center">R:R</th>
            <th class="idx-th" onclick="{pfx}SortBy('sector')">Sector</th>
            <th class="idx-th">Setup</th>
            <th class="idx-th" style="text-align:center">Verdict</th>
          </tr>
        </thead>
        <tbody id="{pfx}-tbody"></tbody>
      </table>
    </div>
  </div>
</div>

<script>
(function(){{
var IDX_DATA = {idx_json};
var _idxFilter = 'ALL';
var _idxSort   = 'score';
var _idxLimit  = 50;  // default top-50; user can expand

var VCOLORS = {{BUY:'#4ade80',WATCH:'#fbbf24',SHORT:'#c084fc',AVOID:'#f87171'}};
var VBGS    = {{BUY:'rgba(34,197,94,0.15)',WATCH:'rgba(245,158,11,0.15)',SHORT:'rgba(168,85,247,0.15)',AVOID:'rgba(239,68,68,0.15)'}};

window.{pfx}Toggle = function() {{
  var p = document.getElementById('{pfx}-full-panel');
  var open = p.style.display !== 'none';
  p.style.display = open ? 'none' : 'block';
  document.getElementById('{pfx}-toggle-chevron').innerHTML = open ? '&#9654;' : '&#9660;';
  if (!open) {pfx}Render();
}};

window.{pfx}SetFilter = function(btn, f) {{
  _idxFilter = f;
  document.querySelectorAll('.{pfx}-pill').forEach(function(b) {{ b.classList.remove('active'); }});
  btn.classList.add('active');
  {pfx}Render();
}};

window.{pfx}SortBy = function(key) {{
  _idxSort = key;
  document.getElementById('{pfx}-sort-sel').value = key;
  {pfx}Render();
}};

window.{pfx}Render = function() {{
  _idxSort = document.getElementById('{pfx}-sort-sel').value;
  var q = (document.getElementById('{pfx}-search').value || '').toLowerCase();

  var rows = IDX_DATA.filter(function(r) {{
    if (_idxFilter !== 'ALL' && r.verdict !== _idxFilter) return false;
    if (q && r.ticker.toLowerCase().indexOf(q) < 0
          && r.sector.toLowerCase().indexOf(q) < 0
          && r.name.toLowerCase().indexOf(q) < 0) return false;
    return true;
  }});

  rows.sort(function(a, b) {{
    if (_idxSort === 'score')  return b.score - a.score;
    if (_idxSort === 'rr')     return b.rr - a.rr;
    if (_idxSort === 'price')  return b.price - a.price;
    if (_idxSort === 'alpha')  return a.ticker.localeCompare(b.ticker);
    if (_idxSort === 'sector') return a.sector.localeCompare(b.sector);
    return 0;
  }});

  var sc_c  = function(s) {{ return s>=75?'#4ade80':s>=55?'#fbbf24':'#f87171'; }};
  var rr_c  = function(r) {{ return r>=3?'#4ade80':r>=2?'#fbbf24':'#f87171'; }};

  var totalMatching = rows.length;
  var displayRows = _idxLimit > 0 ? rows.slice(0, _idxLimit) : rows;

  var html = '';
  displayRows.forEach(function(r) {{
    var vc  = VCOLORS[r.verdict] || '#94a3b8';
    var vbg = VBGS[r.verdict]    || 'rgba(100,116,139,0.12)';
    html += '<tr style="cursor:pointer" onclick="spOpen(\\\''+r.ticker+'\\\')"'
          + ' onmouseover="this.style.background=\\\'var(--surface-alt)\\\'"'
          + ' onmouseout="this.style.background=\\\'\\\'">'
      + '<td class="idx-td" style="font-weight:700;color:var(--primary)">'+r.ticker+'</td>'
      + '<td class="idx-td" style="color:var(--text-muted);font-size:12px">'+r.name+'</td>'
      + '<td class="idx-td" style="text-align:right;font-weight:600">$'+r.price.toFixed(2)+'</td>'
      + '<td class="idx-td" style="text-align:center;font-weight:700;color:'+sc_c(r.score)+'">'+r.score.toFixed(0)+'</td>'
      + '<td class="idx-td" style="text-align:center;color:'+rr_c(r.rr)+'">'+r.rr.toFixed(1)+':1</td>'
      + '<td class="idx-td" style="color:var(--text-muted);font-size:12px">'+r.sector+'</td>'
      + '<td class="idx-td" style="color:var(--text-muted);font-size:12px">'+r.setup+'</td>'
      + '<td class="idx-td" style="text-align:center">'
      +   '<span style="font-size:11px;font-weight:700;padding:2px 8px;border-radius:5px;'
      +     'background:'+vbg+';color:'+vc+'">'+r.verdict+'</span>'
      + '</td></tr>';
  }});
  if (!html) html = '<tr><td colspan="8" style="padding:20px;text-align:center;color:var(--text-muted)">No matching stocks</td></tr>';
  document.getElementById('{pfx}-tbody').innerHTML = html;
  var countTxt = displayRows.length + ' of ' + totalMatching;
  if (totalMatching > displayRows.length) {{
    countTxt += ' <button onclick="{pfx}Expand()" style="margin-left:8px;padding:2px 10px;border-radius:12px;border:1px solid var(--primary);background:var(--surface);color:var(--primary);font-size:11px;font-weight:700;cursor:pointer">Show all '+totalMatching+'</button>';
  }} else if (_idxLimit === 0 && totalMatching > 50) {{
    countTxt += ' <button onclick="{pfx}Collapse()" style="margin-left:8px;padding:2px 10px;border-radius:12px;border:1px solid var(--border);background:var(--surface);color:var(--text-muted);font-size:11px;font-weight:700;cursor:pointer">Collapse to top 50</button>';
  }}
  document.getElementById('{pfx}-count').innerHTML = countTxt;
}};

window.{pfx}Expand = function() {{ _idxLimit = 0; {pfx}Render(); }};
window.{pfx}Collapse = function() {{ _idxLimit = 50; {pfx}Render(); }};
}})();
</script>"""
